-- Migration 627: Learn guides catalog (DB-backed)
-- Moves the Learn Mode guide catalog from the static JSON file
-- (server/data/learnGuides.json) into a DB table with admin CRUD.
-- Seeded with the 117 guides from the JSON file. The controller
-- falls back to the JSON file if the table is missing or empty.

CREATE TABLE IF NOT EXISTS learn_guides (
  id              TEXT PRIMARY KEY,
  title           TEXT NOT NULL,
  category        TEXT NOT NULL,
  difficulty      TEXT NOT NULL DEFAULT 'Easy',
  minutes         INTEGER,
  featured        BOOLEAN NOT NULL DEFAULT FALSE,
  intro           TEXT,
  steps           JSONB NOT NULL DEFAULT '[]',
  skills          TEXT[] NOT NULL DEFAULT '{}',
  tools           JSONB NOT NULL DEFAULT '[]',
  xp              INTEGER NOT NULL DEFAULT 10,
  video_url       TEXT,
  video_provider  TEXT,
  status          TEXT NOT NULL DEFAULT 'published'
                  CHECK (status IN ('published','draft')),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_lg_category ON learn_guides (category);
CREATE INDEX IF NOT EXISTS idx_lg_status ON learn_guides (status);
CREATE INDEX IF NOT EXISTS idx_lg_featured ON learn_guides (featured) WHERE featured;

-- Auto-update updated_at
CREATE OR REPLACE FUNCTION lg_touch_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$;

DROP TRIGGER IF EXISTS lg_updated_at ON learn_guides;
CREATE TRIGGER lg_updated_at
  BEFORE UPDATE ON learn_guides
  FOR EACH ROW EXECUTE FUNCTION lg_touch_updated_at();

-- Seed from the static catalog. Idempotent: only insert ids not present.
INSERT INTO learn_guides
  (id, title, category, difficulty, minutes, featured, intro, steps, skills, tools, xp, status)
SELECT * FROM (VALUES
('fix-leaky-faucet','Fix a Leaky Faucet','plumbing','Easy',30,TRUE,'A dripping faucet wastes gallons a day and usually comes down to a worn washer or O-ring — both cost under a dollar.','["Turn off the water supply valves under the sink, then open the faucet to release remaining pressure.","Remove the handle by unscrewing the decorative cap and the screw underneath it.","Unscrew the packing nut and pull out the stem.","Inspect the rubber washer and O-ring at the bottom of the stem — replace both.","Reassemble in reverse order, turn the supply valves back on, and test for drips."]'::jsonb,ARRAY['Shutoff valve operation','Basic disassembly','Washer replacement'],'[{"name":"Adjustable wrench","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"},{"name":"Flathead + Phillips screwdrivers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=screwdriver%20set&tag=oxsteed-20"},{"name":"Faucet repair kit (washers + O-rings)","rent":null,"buy":"https://www.amazon.com/s?k=faucet%20repair%20kit%20washers%20o-rings&tag=oxsteed-20"}]'::jsonb,10,'published'),
('unclog-drain','Unclog a Drain','plumbing','Easy',20,FALSE,'Most slow drains are a hair-and-soap buildup in the trap — no chemicals needed, just the right tool and a little patience.','["Remove the drain stopper (usually lifts out or unscrews).","Insert a drain snake or zip-it tool at least 12 inches and pull out debris.","Run hot water for 30 seconds to flush loosened buildup.","If still slow, place a bucket under the P-trap, unscrew the slip-joint nuts, clean the trap, and reinstall.","Test the drain and inspect all trap connections for leaks."]'::jsonb,ARRAY['Drain snake use','P-trap removal','Slip-joint fittings'],'[{"name":"Drain snake or zip-it tool","rent":null,"buy":"https://www.amazon.com/s?k=drain%20snake%20clog%20remover&tag=oxsteed-20"},{"name":"Bucket","rent":null,"buy":"https://www.amazon.com/s?k=utility%20bucket&tag=oxsteed-20"},{"name":"Tongue-and-groove pliers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=tongue%20groove%20pliers&tag=oxsteed-20"}]'::jsonb,10,'published'),
('fix-running-toilet','Fix a Running Toilet','plumbing','Medium',45,FALSE,'A toilet that runs after flushing is almost always the flapper or fill valve — both are cheap and beginner-friendly to replace.','["Lift the tank lid and listen: hissing = fill valve issue; water running into bowl = flapper.","To fix the flapper: shut off the supply, flush to empty, unhook the old flapper, snap on the new one.","To fix the fill valve: shut off the supply, flush to empty, unscrew the lock nut at the base, twist in the new valve.","Set the water level to about 1 inch below the overflow tube.","Turn the water back on, let the tank fill, and confirm the running has stopped."]'::jsonb,ARRAY['Toilet tank anatomy','Flapper replacement','Fill valve replacement'],'[{"name":"Universal flapper","rent":null,"buy":"https://www.amazon.com/s?k=universal%20toilet%20flapper&tag=oxsteed-20"},{"name":"Fill valve kit","rent":null,"buy":"https://www.amazon.com/s?k=toilet%20fill%20valve%20replacement&tag=oxsteed-20"},{"name":"Adjustable wrench","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-shower-head','Install a New Shower Head','plumbing','Easy',15,FALSE,'Upgrading a shower head is a 15-minute job that makes a noticeable daily difference — and no tools other than a wrench.','["Turn off the water supply to the shower (or the main shutoff).","Wrap the shower arm threads with 2–3 layers of plumber''s tape (clockwise direction).","Hand-thread the new shower head onto the arm. Tighten with a wrench one quarter-turn past hand-tight — avoid over-tightening.","Turn the water on and check for leaks at the connection.","If it drips, add one more layer of plumber''s tape and retighten."]'::jsonb,ARRAY['Thread sealing','Wrench use','Leak testing'],'[{"name":"Adjustable wrench or channel-lock pliers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"},{"name":"Plumber''s tape (PTFE)","rent":null,"buy":"https://www.amazon.com/s?k=plumber''s%20tape%20PTFE%20teflon&tag=oxsteed-20"}]'::jsonb,10,'published'),
('replace-toilet-fill-valve','Replace a Toilet Fill Valve','plumbing','Medium',45,FALSE,'A hissing or slow-filling toilet usually means the fill valve is worn. A universal replacement takes under an hour and costs less than $15.','["Turn off the supply valve behind the toilet. Flush to empty the tank.","Sponge out remaining water from the tank.","Disconnect the supply line from the bottom of the tank. Unscrew the locknut holding the old fill valve and lift it out.","Adjust the new fill valve height to match your tank depth. Insert it and hand-tighten the locknut from below.","Reconnect the supply line. Turn on the water, set the float to fill 1 inch below the overflow tube, and flush to test."]'::jsonb,ARRAY['Supply valve shutoff','Fill valve anatomy','Float adjustment'],'[{"name":"Universal fill valve kit","rent":null,"buy":"https://www.amazon.com/s?k=toilet%20fill%20valve%20universal&tag=oxsteed-20"},{"name":"Adjustable wrench","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"},{"name":"Sponge or small towel","rent":null,"buy":"https://www.amazon.com/s?k=utility%20sponge&tag=oxsteed-20"}]'::jsonb,25,'published'),
('fix-burst-pipe-temporary','Temporarily Stop a Burst Pipe','plumbing','Hard',30,FALSE,'A burst pipe can release hundreds of gallons an hour. Knowing how to stop the flow buys time until a plumber arrives and limits damage.','["Immediately shut off the main water supply valve — usually near the water meter or where the main enters the house.","Open the lowest faucet in the house to drain remaining pressure from the pipes.","Locate the burst or cracked section. Dry it as thoroughly as possible with rags.","Apply a pipe repair clamp or silicone repair tape tightly over the damaged section — overlap by at least 2 inches on each side.","Slowly restore the water supply and monitor the patch. Call a licensed plumber to make a permanent repair."]'::jsonb,ARRAY['Main shutoff valve location','Emergency pipe clamp application','Water damage mitigation'],'[{"name":"Pipe repair clamp (sized to pipe diameter)","rent":null,"buy":"https://www.amazon.com/s?k=pipe%20repair%20clamp%20emergency&tag=oxsteed-20"},{"name":"Silicone self-fusing repair tape","rent":null,"buy":"https://www.amazon.com/s?k=silicone%20self%20fusing%20repair%20tape&tag=oxsteed-20"},{"name":"Towels and mop","rent":null,"buy":"https://www.amazon.com/s?k=mop%20and%20bucket%20set&tag=oxsteed-20"}]'::jsonb,50,'published'),
('install-water-shutoff-valve','Replace a Water Supply Shutoff Valve','plumbing','Medium',60,FALSE,'A shutoff valve that won''t fully close — or one that drips when open — leaves you unable to make any downstream repair. Replacing it takes an hour and requires only basic plumbing skills.','["Turn off the main water supply. Open a faucet downstream to drain remaining pressure from the line.","Use an adjustable wrench to unscrew the old valve''s compression nuts. Note the pipe diameter (usually 1/2\" or 3/4\") before removing.","Cut back the pipe by 1/2\" with a pipe cutter to expose clean metal. Deburr the cut edge with the reamer on the pipe cutter.","Slide on the new compression nut and ring. Push the new ball valve onto the pipe and tighten the nut hand-tight plus one full turn with a wrench.","Restore the main supply, close the new valve, then slowly open it. Check the compression fitting for drips. One additional quarter-turn will stop a slow drip."]'::jsonb,ARRAY['Main shutoff operation','Pipe cutting','Compression fitting assembly','Leak testing'],'[{"name":"Pipe cutter (1/2\" or 3/4\")","rent":"/tool-rentals?category=plumbing","buy":"https://www.amazon.com/s?k=pipe%20cutter%20tubing%20cutter&tag=oxsteed-20"},{"name":"Adjustable wrench","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"},{"name":"Ball valve with compression fittings (match pipe size)","rent":null,"buy":"https://www.amazon.com/s?k=ball%20valve%20compression%20fitting%201%2F2%20inch&tag=oxsteed-20"}]'::jsonb,25,'published'),
('fix-toilet-wax-ring','Replace a Toilet Wax Ring','plumbing','Hard',90,FALSE,'A toilet that wobbles or leaves water on the floor at the base has a failed wax ring. It''s a messy job, but straightforward — and ignoring it leads to subfloor damage.','["Turn off the supply valve. Flush to empty the tank. Use a sponge and bucket to remove remaining water from the tank and bowl.","Disconnect the supply line. Unscrew the two closet bolts at the toilet base. Lift the toilet straight up and set it on its side on a tarp.","Scrape the old wax off the floor flange and the toilet horn using a putty knife. Clean both surfaces thoroughly.","Press the new wax ring onto the toilet horn (wax side down) or onto the floor flange. Align the toilet over the flange bolts and lower it straight down — don''t shift side to side once wax contacts the flange.","Press down firmly and evenly to seat the wax. Hand-tighten the nuts alternately; snug but not over-tight (cracks the toilet base). Reconnect supply, restore water, flush, and check for leaks."]'::jsonb,ARRAY['Toilet removal and reinstall','Wax ring seating','Closet bolt and flange anatomy'],'[{"name":"Wax ring (with or without horn extension — check flange height)","rent":null,"buy":"https://www.amazon.com/s?k=toilet%20wax%20ring%20with%20horn&tag=oxsteed-20"},{"name":"Putty knife","rent":null,"buy":"https://www.amazon.com/s?k=putty%20knife%20set&tag=oxsteed-20"},{"name":"Adjustable wrench","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=adjustable%20wrench&tag=oxsteed-20"},{"name":"Bucket and sponge","rent":null,"buy":"https://www.amazon.com/s?k=utility%20bucket&tag=oxsteed-20"},{"name":"Tarp or old drop cloth","rent":null,"buy":"https://www.amazon.com/s?k=canvas%20drop%20cloth&tag=oxsteed-20"}]'::jsonb,50,'published'),
('replace-light-switch','Replace a Light Switch','electrical','Easy',15,FALSE,'Swapping a standard single-pole switch is one of the safest electrical tasks — as long as you confirm the circuit is off first.','["Turn off the circuit breaker that controls the switch. Confirm power is off with a non-contact voltage tester.","Unscrew the cover plate and pull the switch out of the box.","Photograph the wiring before disconnecting anything.","Transfer wires to the new switch: black to brass, marked-white to brass, bare copper to green.","Push the switch back in, screw it down, replace the cover plate, and restore power."]'::jsonb,ARRAY['Breaker shutoff','Voltage testing','Basic wiring connections'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester&tag=oxsteed-20"},{"name":"Flathead + Phillips screwdrivers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=screwdriver%20set&tag=oxsteed-20"},{"name":"Replacement light switch","rent":null,"buy":"https://www.amazon.com/s?k=single%20pole%20light%20switch&tag=oxsteed-20"}]'::jsonb,10,'published'),
('install-ceiling-fan','Install a Ceiling Fan','electrical','Medium',90,FALSE,'Installing a fan is manageable if the existing box is fan-rated. If you''re replacing a light fixture, verify the box before lifting anything.','["Turn off the circuit breaker. Confirm no power with a voltage tester. Verify the ceiling box is fan-rated.","Install the mounting bracket over the box per the fan''s instructions.","Assemble the motor and canopy on the ground, then hang from the bracket hook.","Connect wiring: black to black, white to white, bare to bare. Blue wire (if present) connects to the light kit or a separate switch.","Attach blades and the light kit. Restore power and test all speeds and the light."]'::jsonb,ARRAY['Fan-rated box identification','Wire connections','Blade installation'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester&tag=oxsteed-20"},{"name":"Drill + bits","rent":"/tool-rentals?category=power-tools","buy":null},{"name":"Ladder (6 ft minimum)","rent":"/tool-rentals?category=access","buy":null}]'::jsonb,25,'published'),
('reset-gfci','Reset a GFCI Outlet','electrical','Easy',5,TRUE,'GFCI outlets protect against shock in wet areas. When one trips, it can cut power to several outlets downstream — the tripped outlet is often in a different room.','["Find the outlet with TEST and RESET buttons — it may not be in the same room as the dead outlet.","Check for moisture or visible damage before touching anything.","Press the RESET button firmly until it clicks. Power should restore immediately.","Test with a lamp or outlet tester to confirm.","If the outlet trips again right away, stop and call an electrician — there''s an underlying fault."]'::jsonb,ARRAY['GFCI identification','Circuit tracing','Knowing when to stop'],'[{"name":"Outlet tester","rent":null,"buy":"https://www.amazon.com/s?k=outlet%20circuit%20tester&tag=oxsteed-20"}]'::jsonb,10,'published'),
('replace-outlet','Replace an Electrical Outlet','electrical','Medium',30,FALSE,'A cracked or sparking outlet is a fire hazard. Replacing it is a straightforward job with the right safety steps.','["Turn off the circuit breaker for that outlet. Use a non-contact voltage tester to confirm no power.","Unscrew the cover plate, then the outlet screws. Pull the outlet out of the box carefully.","Photograph the existing wire connections. Disconnect wires from the old outlet.","Connect wires to the new outlet: black to brass (hot), white to silver (neutral), bare/green to green (ground).","Fold wires neatly into the box. Secure the outlet, replace the cover plate, restore power, and test with an outlet tester."]'::jsonb,ARRAY['Breaker shutoff','Voltage testing','Wire terminal connections','Hot/neutral/ground identification'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester&tag=oxsteed-20"},{"name":"Flathead + Phillips screwdrivers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=screwdriver%20set&tag=oxsteed-20"},{"name":"Replacement outlet (duplex receptacle)","rent":null,"buy":"https://www.amazon.com/s?k=duplex%20electrical%20outlet%2015%20amp&tag=oxsteed-20"},{"name":"Outlet tester","rent":null,"buy":"https://www.amazon.com/s?k=outlet%20circuit%20tester&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-dimmer-switch','Install a Dimmer Switch','electrical','Medium',30,FALSE,'A dimmer gives a room mood control and can cut lighting energy use by up to 20%. Match the dimmer to your bulb type or it will hum or flicker.','["Turn off the circuit breaker. Verify no power at the switch with a voltage tester.","Remove the cover plate and pull out the switch. Photograph wiring.","Note the dimmer''s load capacity (usually 150W–600W) and verify it fits your bulb total.","Connect the dimmer leads to the house wires: typically two black leads to hot wires, green/bare to ground. Consult the included diagram.","Fold wires into the box, seat the dimmer, attach the cover, restore power, and test the full range."]'::jsonb,ARRAY['Load calculation','Multi-wire dimmer wiring','Bulb compatibility check'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester&tag=oxsteed-20"},{"name":"Flathead + Phillips screwdrivers","rent":"/tool-rentals?category=hand-tools","buy":"https://www.amazon.com/s?k=screwdriver%20set&tag=oxsteed-20"},{"name":"LED-compatible dimmer switch","rent":null,"buy":"https://www.amazon.com/s?k=LED%20dimmer%20switch%20single%20pole&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-light-fixture','Replace a Light Fixture','electrical','Medium',60,FALSE,'Swapping a fixture is mostly mechanical — the wiring is the same three connections every time. The challenge is weight and working overhead.','["Turn off the breaker. Confirm no power with a voltage tester at the fixture wires.","Support the old fixture while you unscrew the mounting screws. Don''t let it hang by its wires.","Disconnect the three wire connections: black to black (hot), white to white (neutral), bare/green to green (ground).","Attach the new fixture''s mounting bracket to the ceiling box. Connect the matching wires with wire nuts.","Tuck wires into the canopy, attach to the mounting bracket, install bulbs, restore power, and test."]'::jsonb,ARRAY['Overhead work safety','Wire nut connections','Fixture support during install'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester&tag=oxsteed-20"},{"name":"Ladder (6 ft minimum)","rent":"/tool-rentals?category=access","buy":null},{"name":"Phillips screwdriver + wire nuts","rent":null,"buy":"https://www.amazon.com/s?k=wire%20nuts%20assorted%20electrical&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-smart-switch','Install a Smart Light Switch','electrical','Medium',45,FALSE,'Smart switches let you control lights by voice, schedule, or app — without replacing every bulb. Most require a neutral wire; this guide shows you how to identify it and wire the switch safely.','["Turn off the breaker for the circuit. Confirm power is off with a non-contact voltage tester before touching any wires.","Remove the old switch. Photograph the existing wiring before disconnecting anything.","Identify the wires: black (hot), white (neutral), bare or green (ground). Smart switches need all three — if you only have two, check for a neutral wire bundled in the back of the box.","Connect wires per the smart switch diagram: hot to LINE, neutral to NEUTRAL, ground to GROUND. Use the included wire nuts or push-in connectors.","Push the switch into the box and secure with screws. Restore power. Follow the manufacturer app to pair the switch to your Wi-Fi."]'::jsonb,ARRAY['Voltage testing','Wire identification','App pairing'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester%20electrical&tag=oxsteed-20"},{"name":"Flathead and Phillips screwdrivers","rent":null,"buy":"https://www.amazon.com/s?k=screwdriver%20set%20flathead%20phillips&tag=oxsteed-20"},{"name":"Smart switch (e.g. Kasa, Leviton, Lutron)","rent":null,"buy":"https://www.amazon.com/s?k=smart%20light%20switch%20wifi%20neutral%20wire&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-usb-outlet','Replace an Outlet with a USB Charging Outlet','electrical','Easy',30,FALSE,'USB outlets replace a standard wall outlet and add built-in USB-A or USB-C ports — no adapter block needed. It is one of the safest DIY electrical swaps because the wiring is identical to a regular outlet.','["Turn off the breaker and verify power is off with a voltage tester.","Remove the cover plate and unscrew the old outlet from the box. Pull the outlet out — note which wires go to which screw terminals.","Disconnect the old outlet: black wire from brass (hot) screw, white wire from silver (neutral) screw, bare/green from green (ground) screw.","Connect wires to the new USB outlet in the same positions. Tighten each screw firmly — a loose connection causes heat and fire risk.","Push the outlet back into the box, secure with screws, and attach the cover plate. Restore power and test with a phone."]'::jsonb,ARRAY['Outlet wiring','Voltage testing','Wire termination'],'[{"name":"Non-contact voltage tester","rent":null,"buy":"https://www.amazon.com/s?k=non%20contact%20voltage%20tester%20electrical&tag=oxsteed-20"},{"name":"Flathead screwdriver","rent":null,"buy":"https://www.amazon.com/s?k=flathead%20screwdriver&tag=oxsteed-20"},{"name":"USB outlet (USB-A+C combo)","rent":null,"buy":"https://www.amazon.com/s?k=usb%20outlet%20wall%20charger%20built%20in%20usb-c&tag=oxsteed-20"}]'::jsonb,10,'published'),
('replace-hvac-filter','Replace Your HVAC Filter','hvac','Easy',10,TRUE,'A clogged filter makes your system work harder, raises your energy bill, and shortens the unit''s life. Replace it every 1–3 months.','["Find the filter slot — typically on the return air vent or at the air handler unit.","Note the size printed on the old filter frame before buying a replacement.","Turn off the thermostat. Slide out the old filter and note the airflow direction arrow.","Slide in the new filter with the arrow pointing toward the unit (away from the return duct).","Write the install date on the frame with a marker, then turn the thermostat back on."]'::jsonb,ARRAY['Filter sizing','Airflow direction','Maintenance schedule'],'[{"name":"Pleated HVAC filter (match your size)","rent":null,"buy":"https://www.amazon.com/s?k=HVAC%20air%20filter%20pleated&tag=oxsteed-20"},{"name":"Permanent marker","rent":null,"buy":"https://www.amazon.com/s?k=permanent%20marker%20sharpie&tag=oxsteed-20"}]'::jsonb,10,'published'),
('clean-condensate-drain','Clear Your AC Condensate Drain','hvac','Easy',20,FALSE,'A clogged condensate drain causes water to back up into the drain pan and can shut down your AC or cause ceiling damage. Takes 5 minutes to prevent.','["Turn off the AC at the thermostat.","Find the condensate drain line — usually a white PVC pipe near the air handler leading outside.","Locate the clean-out cap and remove it.","Pour 1 cup of distilled white vinegar into the opening. Wait 30 minutes.","Flush with water, then restore power and confirm no water backs up at the drain pan."]'::jsonb,ARRAY['Condensate system basics','Preventive AC maintenance'],'[{"name":"Distilled white vinegar","rent":null,"buy":"https://www.amazon.com/s?k=distilled%20white%20vinegar%20gallon&tag=oxsteed-20"},{"name":"Wet/dry vacuum (for severe clogs)","rent":"/tool-rentals?category=cleaning","buy":null}]'::jsonb,10,'published'),
('seal-hvac-ducts','Seal Leaky HVAC Ducts','hvac','Medium',60,FALSE,'Leaky ducts can account for 20–30% of conditioned air loss. Sealing them with mastic or foil tape pays back in lower energy bills within a year.','["Turn off the HVAC system. Use a flashlight to inspect accessible ducts in the attic, basement, or crawl space for gaps, disconnections, and holes.","Mark all leaks with a marker. For small gaps, apply HVAC-rated foil tape — stretch it flat and press firmly from the center out.","For larger gaps or joints, brush water-based mastic sealant onto the duct surface 2 inches beyond the leak. Let it dry fully.","Wrap duct insulation back over any sections you had to peel back. Secure with tape.","Turn the system back on and hold your hand near sealed areas to feel for airflow — properly sealed ducts produce no draft."]'::jsonb,ARRAY['Duct system navigation','Mastic application','Foil tape technique'],'[{"name":"HVAC mastic sealant","rent":null,"buy":"https://www.amazon.com/s?k=HVAC%20duct%20mastic%20sealant&tag=oxsteed-20"},{"name":"HVAC foil tape","rent":null,"buy":"https://www.amazon.com/s?k=HVAC%20foil%20tape%20metal%20duct&tag=oxsteed-20"},{"name":"Paintbrush (for mastic)","rent":null,"buy":"https://www.amazon.com/s?k=chip%20brush%20set&tag=oxsteed-20"},{"name":"Flashlight or headlamp","rent":null,"buy":"https://www.amazon.com/s?k=headlamp%20flashlight&tag=oxsteed-20"}]'::jsonb,25,'published'),
('clean-dryer-vent','Clean Your Dryer Vent','hvac','Easy',30,FALSE,'Lint buildup in the dryer vent is the leading cause of residential dryer fires. Clean it once a year — or more often if you notice clothes taking longer to dry.','["Unplug the dryer. If gas, turn off the gas supply valve.","Pull the dryer away from the wall and disconnect the vent duct from the back of the unit.","Insert a dryer vent brush kit into the duct and rotate it through the full length, dislodging lint.","Vacuum up all lint from inside the duct, behind the dryer, and at the exterior vent cap.","Reattach the duct with foil tape (not plastic tape). Push the dryer back, restore power, and run a 10-minute heat cycle to confirm airflow."]'::jsonb,ARRAY['Vent duct disassembly','Brush kit use','Airflow testing'],'[{"name":"Dryer vent cleaning brush kit","rent":null,"buy":"https://www.amazon.com/s?k=dryer%20vent%20cleaning%20brush%20kit&tag=oxsteed-20"},{"name":"Vacuum with hose attachment","rent":"/tool-rentals?category=cleaning","buy":null},{"name":"HVAC foil tape","rent":null,"buy":"https://www.amazon.com/s?k=HVAC%20foil%20tape&tag=oxsteed-20"}]'::jsonb,10,'published'),
('insulate-hot-water-pipes','Insulate Hot Water Pipes','hvac','Easy',45,FALSE,'Insulating accessible hot water pipes reduces heat loss, lowers water heating costs, and means you get hot water at the tap faster.','["Measure the diameter of your pipes — most residential supply lines are 1/2\" or 3/4\".","Purchase foam pipe insulation sleeves that match the pipe diameter.","Starting from the water heater, slide the foam sleeves over the pipes. The sleeves are pre-slit — pinch them open and press onto the pipe.","Butt sleeve joints tightly together. At elbows, cut the foam at 45 degrees so the joints meet cleanly.","Secure all seams and joints with foil HVAC tape or specialty pipe insulation tape."]'::jsonb,ARRAY['Pipe diameter measurement','Foam sleeve fitting','Elbow cutting technique'],'[{"name":"Foam pipe insulation sleeves","rent":null,"buy":"https://www.amazon.com/s?k=foam%20pipe%20insulation%20sleeves&tag=oxsteed-20"},{"name":"Utility knife","rent":null,"buy":"https://www.amazon.com/s?k=utility%20knife%20box%20cutter&tag=oxsteed-20"},{"name":"Pipe insulation tape or foil tape","rent":null,"buy":"https://www.amazon.com/s?k=pipe%20insulation%20tape&tag=oxsteed-20"}]'::jsonb,10,'published'),
('patch-drywall','Patch a Drywall Hole','carpentry','Medium',60,FALSE,'A fist-sized hole can be made invisible with the right patch and two thin coats of compound — the key is feathering the edges, not building them up.','["Cut the damaged area into a clean square with a drywall saw.","Cut a drywall patch slightly larger than the hole; score it to leave a paper-backing flap for bonding.","Apply joint compound around the hole, press the patch in place using the paper flap.","Apply a thin first coat feathered 4–6 inches beyond the patch edges. Let dry completely.","Sand lightly, apply a second thin coat feathered even wider, sand again, then prime and paint."]'::jsonb,ARRAY['Drywall cutting','Mud application','Feathering technique','Surface prep'],'[{"name":"Drywall repair patch","rent":null,"buy":"https://www.amazon.com/s?k=drywall%20repair%20patch%20kit&tag=oxsteed-20"},{"name":"Joint compound (pre-mixed)","rent":null,"buy":"https://www.amazon.com/s?k=joint%20compound%20pre%20mixed&tag=oxsteed-20"},{"name":"4\" and 8\" putty knives","rent":"/tool-rentals?category=painting","buy":"https://www.amazon.com/s?k=putty%20knife%20set%20drywall&tag=oxsteed-20"},{"name":"Sanding sponge","rent":null,"buy":"https://www.amazon.com/s?k=drywall%20sanding%20sponge&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-door-handle','Replace a Door Handle','carpentry','Easy',30,FALSE,'Most door handles use standard sizing — the new set includes a template that makes this a clean swap with no measuring.','["Remove the existing handle by unscrewing the mounting screws on the interior rose plate.","Pull both sides out and unscrew the latch from the door edge.","Use the included template to confirm the hole sizing matches your door.","Insert the new latch and secure with edge screws.","Thread the exterior handle through and align the interior handle. Tighten the mounting screws."]'::jsonb,ARRAY['Door hardware sizing','Latch alignment','Rose plate mounting'],'[{"name":"Phillips screwdriver or drill","rent":"/tool-rentals?category=power-tools","buy":"https://www.amazon.com/s?k=cordless%20screwdriver&tag=oxsteed-20"},{"name":"Replacement door handle set","rent":null,"buy":"https://www.amazon.com/s?k=interior%20door%20handle%20set&tag=oxsteed-20"}]'::jsonb,10,'published'),
('hang-floating-shelves','Hang Floating Shelves','carpentry','Easy',45,FALSE,'Floating shelves are one of the most-requested handyperson jobs. The whole project hinges on hitting studs and keeping things level.','["Use a stud finder to locate studs behind the wall. Mark them with a light pencil mark.","Hold the shelf bracket against the wall at your desired height. Use a level to confirm horizontal, then mark the mounting holes.","Drill pilot holes into the studs at your marks. If no stud is available at all mounting points, use toggle bolts for the drywall-only holes.","Screw the brackets into the wall securely. Slide the shelf onto the brackets or attach per manufacturer instructions.","Load the shelf evenly and test for wobble. Tighten any loose screws."]'::jsonb,ARRAY['Stud finding','Leveling','Wall anchor selection'],'[{"name":"Stud finder","rent":null,"buy":"https://www.amazon.com/s?k=stud%20finder%20wall%20scanner&tag=oxsteed-20"},{"name":"Level (24\" or torpedo)","rent":null,"buy":"https://www.amazon.com/s?k=24%20inch%20level%20torpedo%20level&tag=oxsteed-20"},{"name":"Drill + bits","rent":"/tool-rentals?category=power-tools","buy":null},{"name":"Floating shelf with mounting hardware","rent":null,"buy":"https://www.amazon.com/s?k=floating%20shelf%20with%20brackets&tag=oxsteed-20"}]'::jsonb,10,'published'),
('fix-squeaky-floor','Fix a Squeaky Floor','carpentry','Medium',60,FALSE,'Most floor squeaks happen where the subfloor has separated from a joist. A few well-placed screws from below — or a squeak-specific kit from above — silences them permanently.','["Walk the floor to identify the exact squeak location. Mark it with tape.","If you have basement or crawl access below: have a helper stand on the spot while you push up from below to feel the flex. Drive a short screw up through the subfloor into the joist — don''t penetrate the finished floor.","If access is from above: use a squeak-eliminator kit that drives a special screw through the finish floor, then snaps the head off flush.","For hardwood over joist: drill a pilot hole at a slight angle and drive a trim-head screw into the joist below. Countersink and fill with a color-matched filler.","Test by walking over the area. If the squeak persists, repeat 2–3 inches away along the joist line."]'::jsonb,ARRAY['Subfloor joist location','Below-floor screw driving','Squeak-kit method'],'[{"name":"Squeak-Ender or Squeeeeek No More kit","rent":null,"buy":"https://www.amazon.com/s?k=squeeeeek%20no%20more%20floor%20repair%20kit&tag=oxsteed-20"},{"name":"Drill + bits","rent":"/tool-rentals?category=power-tools","buy":null},{"name":"Color-matched wood filler","rent":null,"buy":"https://www.amazon.com/s?k=wood%20filler%20color%20match&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-window-screen','Install or Replace a Window Screen','carpentry','Easy',30,FALSE,'A torn window screen is easy to re-screen with a roll of mesh and a spline tool. It''s also the same process for installing a screen in a frame.','["Remove the old spline (the rubber cord that holds the mesh) using a flathead screwdriver.","Pull out the torn mesh. Clean the channel in the frame.","Cut new mesh slightly larger than the frame on all sides.","Lay the mesh over the frame. Starting from a corner, press the spline and mesh into the channel using the convex wheel of the spline roller.","Work around all four sides, keeping the mesh taut (not stretched). Trim excess mesh with a utility knife."]'::jsonb,ARRAY['Spline removal and installation','Mesh tensioning','Knife trimming'],'[{"name":"Screen spline roller tool","rent":null,"buy":"https://www.amazon.com/s?k=screen%20spline%20roller%20tool&tag=oxsteed-20"},{"name":"Replacement fiberglass mesh roll","rent":null,"buy":"https://www.amazon.com/s?k=window%20screen%20mesh%20replacement%20roll&tag=oxsteed-20"},{"name":"Screen spline (match your frame groove)","rent":null,"buy":"https://www.amazon.com/s?k=window%20screen%20spline%20replacement&tag=oxsteed-20"},{"name":"Utility knife","rent":null,"buy":"https://www.amazon.com/s?k=utility%20knife%20box%20cutter&tag=oxsteed-20"}]'::jsonb,10,'published'),
('install-baseboards','Install Baseboard Trim','carpentry','Medium',120,FALSE,'Baseboards hide the gap between flooring and drywall and give a room a finished look. Good results come from accurate miter cuts at corners and tight caulk at the top edge — not from luck.','["Measure each wall section and add 10% for waste. Mark stud locations with a stud finder — you need to nail into studs.","Cut outside corners at 45 degrees with a miter saw. For inside corners, cope the second piece (cut the profile with a coping saw) rather than mitering both — cope joints stay tight when wood expands.","Dry-fit all pieces before nailing. Trim and adjust until joints close cleanly.","Nail each piece into studs using a finish nailer or hand-nail with 2\" finish nails. Keep nails 6\" from ends to prevent splitting.","Fill nail holes with wood filler, let dry, sand flush. Caulk the top edge against the wall. Prime and paint the trim."]'::jsonb,ARRAY['Miter cuts','Coping joints','Finish nailing','Caulking'],'[{"name":"Miter saw","rent":"/tool-rentals?category=carpentry","buy":null},{"name":"Finish nailer + compressor","rent":"/tool-rentals?category=carpentry","buy":null},{"name":"Coping saw","rent":null,"buy":"https://www.amazon.com/s?k=coping%20saw%20for%20trim%20work&tag=oxsteed-20"},{"name":"Stud finder","rent":null,"buy":"https://www.amazon.com/s?k=stud%20finder%20wall%20scanner&tag=oxsteed-20"}]'::jsonb,25,'published'),
('repair-wood-fence','Replace a Damaged Wood Fence Board','carpentry','Medium',90,FALSE,'Individual fence boards rot or break long before the posts give out. Swapping them one at a time is far cheaper than a full fence replacement and keeps the fence looking maintained.','["Identify all damaged boards. Check for rot by poking with a screwdriver — rot is soft and the tip sinks in easily.","Remove damaged boards by prying off with a flat bar. Start at the nails and work the board loose to avoid damaging adjacent boards.","Measure the opening: width, height, and thickness of the existing boards. Buy matching cedar or pressure-treated boards.","Cut new boards to length. Pre-drill nail holes near the ends to prevent splitting. For cedar, leave a 1/8\" gap between boards for expansion.","Nail each board to the rails using 1-5/8\" galvanized or stainless deck screws (not nails — screws hold longer outdoors). Apply wood preservative to the cut ends."]'::jsonb,ARRAY['Rot detection','Pry bar technique','Galvanized fasteners','Expansion gaps'],'[{"name":"Flat pry bar","rent":null,"buy":"https://www.amazon.com/s?k=flat%20pry%20bar%20demolition%20bar&tag=oxsteed-20"},{"name":"Drill/driver","rent":null,"buy":"https://www.amazon.com/s?k=cordless%20drill%20driver&tag=oxsteed-20"},{"name":"Circular saw or handsaw","rent":"/tool-rentals?category=carpentry","buy":null}]'::jsonb,25,'published'),
('paint-a-wall','Prep and Paint a Room Wall','painting','Medium',180,FALSE,'Good prep determines the result — patching, sanding, and taping matter more than the paint itself.','["Patch nail holes and dings with spackling. Sand smooth when dry.","Wipe walls with a damp cloth to remove dust and grease. Let dry fully.","Apply painter''s tape along trim, outlets, and edges. Lay a drop cloth.","Cut in edges with an angled brush: corners, tape lines, ceiling edge.","Roll the main wall area in a W pattern with a 3/8\" nap roller. Apply two coats, letting the first dry between coats."]'::jsonb,ARRAY['Surface prep','Cutting in','Rolling technique','Two-coat application'],'[{"name":"Paint roller and tray","rent":"/tool-rentals?category=painting","buy":"https://www.amazon.com/s?k=paint%20roller%20tray%20set&tag=oxsteed-20"},{"name":"2\" angled brush","rent":null,"buy":"https://www.amazon.com/s?k=angled%20paint%20brush%202%20inch&tag=oxsteed-20"},{"name":"Painter''s tape","rent":null,"buy":"https://www.amazon.com/s?k=painter''s%20tape%20blue&tag=oxsteed-20"},{"name":"Drop cloth","rent":null,"buy":"https://www.amazon.com/s?k=canvas%20drop%20cloth&tag=oxsteed-20"}]'::jsonb,25,'published'),
('prep-and-prime-wall','Prep and Prime a Wall Before Painting','painting','Easy',60,FALSE,'Skipping primer over fresh patches, stains, or new drywall leads to visible bleed-through that shows even after two topcoats. Primer is insurance.','["Fill all holes with spackling or lightweight compound. Let dry, then sand flush.","Lightly sand glossy surfaces with 220-grit paper so primer adheres — wipe off dust with a tack cloth.","Mask trim, outlets, and the ceiling edge with painter''s tape.","Roll primer onto the wall using a 3/8\" nap roller, cutting in the edges first with a brush.","Let primer dry fully per the can instructions (typically 1–2 hours). Inspect for any remaining stains — apply a second prime coat if needed."]'::jsonb,ARRAY['Hole filling','Surface sanding','Primer application'],'[{"name":"Spackling compound","rent":null,"buy":"https://www.amazon.com/s?k=spackling%20compound%20paste&tag=oxsteed-20"},{"name":"Drywall primer (PVA for new drywall, stain-blocking for water stains)","rent":null,"buy":"https://www.amazon.com/s?k=drywall%20primer%20PVA&tag=oxsteed-20"},{"name":"Paint roller + tray","rent":"/tool-rentals?category=painting","buy":"https://www.amazon.com/s?k=paint%20roller%20tray%20set&tag=oxsteed-20"},{"name":"Painter''s tape","rent":null,"buy":"https://www.amazon.com/s?k=painter''s%20tape%20blue&tag=oxsteed-20"}]'::jsonb,10,'published'),
('paint-trim-and-baseboards','Paint Trim and Baseboards','painting','Medium',90,FALSE,'Crisp trim paint is what separates an amateur paint job from a professional one. The secret is tight masking, thin coats, and patience at the brush.','["Apply painter''s tape along the floor edge and any wall surface adjacent to trim.","Lightly sand the trim with 220-grit to degloss the existing paint. Wipe clean.","Load a 1.5\" angled brush sparingly and apply a thin first coat — trim paint sags easily.","Let the first coat dry fully (follow the can label). Lightly scuff with fine-grit paper, then apply a second coat.","Remove tape while the paint is still slightly tacky (not wet, not bone dry) to avoid peeling the edge."]'::jsonb,ARRAY['Masking for trim','Thin-coat brush technique','Tape removal timing'],'[{"name":"1.5\" angled sash brush","rent":null,"buy":"https://www.amazon.com/s?k=angled%20sash%20brush%201.5%20inch&tag=oxsteed-20"},{"name":"Painter''s tape (thin profile)","rent":null,"buy":"https://www.amazon.com/s?k=painter''s%20tape%20fine%20edge&tag=oxsteed-20"},{"name":"Semi-gloss or gloss trim paint","rent":null,"buy":"https://www.amazon.com/s?k=semi%20gloss%20trim%20paint%20white&tag=oxsteed-20"},{"name":"220-grit sanding sponge","rent":null,"buy":"https://www.amazon.com/s?k=220%20grit%20sanding%20sponge&tag=oxsteed-20"}]'::jsonb,25,'published'),
('touch-up-and-color-match','Touch Up Paint and Match Colors','painting','Medium',30,FALSE,'Touch-ups that don''t match are worse than the original damage. The challenge is sheen and color drift — here''s how to make them invisible.','["Identify the original paint if possible — check closets, garages, or the utility room for leftover cans.","If no leftover paint: take a paint chip (a quarter-size peeled section) to a paint store for spectrophotometer matching.","Sand the damaged area lightly and apply primer if it''s bare drywall.","Apply the touch-up paint in thin coats, feathering 4–6 inches around the damage. Match the application texture — roller for rolled walls, brush strokes for brushed areas.","Let dry and assess in natural light. A fresh small patch will look slightly different until it cures fully (1–2 weeks) — inform the client."]'::jsonb,ARRAY['Color matching process','Feathered touch-up technique','Sheen matching'],'[{"name":"Paint chip (for store matching)","rent":null,"buy":null},{"name":"3\" foam mini roller","rent":null,"buy":"https://www.amazon.com/s?k=mini%20foam%20roller%20set&tag=oxsteed-20"},{"name":"1\" chip brush","rent":null,"buy":"https://www.amazon.com/s?k=chip%20brush%20set&tag=oxsteed-20"}]'::jsonb,25,'published'),
('apply-exterior-caulk','Caulk Exterior Gaps and Trim','painting','Easy',60,FALSE,'Exterior caulk seals gaps around windows, doors, and trim that let drafts, water, and insects in. Applied before painting, it gives a professional finish. Applied alone, it adds years to paint life by preventing moisture infiltration.','["Inspect all exterior joints: where trim meets siding, where window frames meet the wall, around door frames. Mark gaps wider than 1/4\" — those need backer rod before caulk.","Remove old cracked caulk with a caulk removal tool or utility knife. Clean the surface with a stiff brush and let it dry completely.","Load a paintable siliconized acrylic caulk into the gun. Cut the tip at a 45-degree angle — a smaller hole gives you more control.","Apply in a steady bead, moving the gun at a consistent pace. Don''t stop mid-joint. For wide gaps, use two thin passes rather than one thick one.","Smooth with a wet finger or caulk smoothing tool within 30 seconds. Remove excess with a damp cloth. Let cure per label before painting (usually 2–4 hours)."]'::jsonb,ARRAY['Caulk gun control','Surface prep','Smoothing technique','Backer rod use'],'[{"name":"Caulk gun","rent":null,"buy":"https://www.amazon.com/s?k=caulk%20gun%20exterior%20smooth%20rod&tag=oxsteed-20"},{"name":"Exterior paintable siliconized acrylic caulk","rent":null,"buy":"https://www.amazon.com/s?k=exterior%20paintable%20caulk%20siliconized%20acrylic&tag=oxsteed-20"},{"name":"Caulk removal tool","rent":null,"buy":"https://www.amazon.com/s?k=caulk%20remover%20tool%20scraper&tag=oxsteed-20"}]'::jsonb,10,'published'),
('paint-cabinets','Paint Kitchen Cabinets','painting','Hard',240,FALSE,'Cabinet painting transforms a kitchen at a fraction of replacement cost — but it requires careful prep, the right primer, and patience between coats. Shortcuts here are always visible.','["Remove all doors and drawer fronts. Label each with painter''s tape and a marker so they go back in the right position.","Clean all surfaces with TSP substitute or a degreaser. Grease and cooking film prevent adhesion — this step determines whether paint lasts 3 years or 10.","Lightly sand all surfaces with 120-grit, then 180-grit. Sand with the grain. Wipe dust with a tack cloth.","Apply a shellac-based or bonding primer — not latex. This is non-negotiable on laminate, melamine, or previously varnished cabinets. Let dry fully, sand lightly with 220-grit.","Apply two coats of cabinet-specific alkyd or waterborne alkyd paint with a foam roller (boxes) and a small brush (profiles). Let each coat cure fully — 24 hours minimum — before rehanging doors."]'::jsonb,ARRAY['Surface degreasing','Bonding primer selection','Foam roller technique','Cure time discipline'],'[{"name":"TSP substitute cleaner","rent":null,"buy":"https://www.amazon.com/s?k=tsp%20substitute%20heavy%20duty%20cleaner%20degreaser&tag=oxsteed-20"},{"name":"Shellac-based primer (e.g. BIN)","rent":null,"buy":"https://www.amazon.com/s?k=shellac%20based%20primer%20BIN%20Zinsser%20cabinet&tag=oxsteed-20"},{"name":"Cabinet paint (waterborne alkyd)","rent":null,"buy":"https://www.amazon.com/s?k=waterborne%20alkyd%20cabinet%20paint%20trim&tag=oxsteed-20"},{"name":"Foam rollers (4\") + trim brush set","rent":null,"buy":"https://www.amazon.com/s?k=4%20inch%20foam%20roller%20cabinet%20painting%20set&tag=oxsteed-20"}]'::jsonb,50,'published'),
('change-oil','Change Your Engine Oil','car-care','Medium',45,FALSE,'An oil change is the highest-leverage maintenance task you own — wrong intervals cost engines. Getting comfortable doing it yourself saves money every 5,000 miles.','["Look up the correct oil spec (e.g. 5W-30) and filter for your year/make/model.","Warm the engine 2 minutes, turn it off. Jack up the car and set it on jack stands.","Place a drain pan under the drain plug, remove the plug, and let the oil drain fully (5–10 min).","Remove the old oil filter with a filter wrench. Lightly coat the new filter gasket with fresh oil, hand-tighten.","Reinstall the drain plug, fill from the top, check level with the dipstick, run the engine briefly, and check for leaks."]'::jsonb,ARRAY['Jack and stand safety','Oil spec lookup','Filter replacement','Drain plug torque'],'[{"name":"Floor jack and jack stands","rent":"/tool-rentals?category=automotive","buy":null},{"name":"Oil filter wrench","rent":"/tool-rentals?category=automotive","buy":"https://www.amazon.com/s?k=oil%20filter%20wrench&tag=oxsteed-20"},{"name":"Drain pan","rent":null,"buy":"https://www.amazon.com/s?k=oil%20drain%20pan&tag=oxsteed-20"},{"name":"Correct oil + filter for your vehicle","rent":null,"buy":"https://www.amazon.com/s?k=motor%20oil%205w30&tag=oxsteed-20"}]'::jsonb,25,'published'),
('replace-wipers','Replace Windshield Wipers','car-care','Easy',10,FALSE,'Streaking wipers are a safety issue. Replacing them takes 10 minutes and no tools — just the right size for your car.','["Look up the correct blade size for your driver and passenger sides (they''re often different).","Lift the wiper arm away from the windshield until it locks raised.","Press the tab where the blade meets the arm and slide the old blade off.","Hook the new blade onto the arm and press until it clicks.","Gently lower the arm back to the glass. Repeat for the other side."]'::jsonb,ARRAY['Blade sizing','Hook-style connector','Safe arm handling'],'[{"name":"Replacement wiper blades (check your vehicle size)","rent":null,"buy":"https://www.amazon.com/s?k=windshield%20wiper%20blades&tag=oxsteed-20"}]'::jsonb,10,'published'),
('rotate-tires','Rotate Your Tires','car-care','Medium',30,FALSE,'Rotating tires every 5,000–7,500 miles evens out wear and extends their life by tens of thousands of miles. It requires jack stands and a torque wrench — but no special skills.','["Loosen all lug nuts on all four wheels while the car is still on the ground (break torque only — don''t remove).","Jack up one end of the car and set securely on two jack stands. Remove both wheels.","Move wheels in the correct rotation pattern for your vehicle (front-to-back same side for non-directional; X-pattern for non-directional all-season). Check your owner''s manual.","Repeat on the other end. Torque all lug nuts to spec in a star pattern (typically 80–100 ft-lb for passenger cars).","Lower the car and check tire pressure on all four tires before driving."]'::jsonb,ARRAY['Jack and stand safety','Rotation pattern identification','Torque wrench use'],'[{"name":"Floor jack and four jack stands","rent":"/tool-rentals?category=automotive","buy":null},{"name":"Torque wrench (0–150 ft-lb)","rent":"/tool-rentals?category=automotive","buy":"https://www.amazon.com/s?k=torque%20wrench%20150%20ft%20lb&tag=oxsteed-20"},{"name":"Breaker bar or impact wrench","rent":"/tool-rentals?category=automotive","buy":"https://www.amazon.com/s?k=breaker%20bar%201%2F2%20inch%20drive&tag=oxsteed-20"}]'::jsonb,25,'published'),
('replace-cabin-air-filter','Replace Your Cabin Air Filter','car-care','Easy',10,FALSE,'A clogged cabin air filter reduces AC airflow and fills your car with allergens. It''s a 10-minute job that dealers charge $50+ for in labor alone.','["Look up the cabin air filter location for your specific vehicle — most are behind the glove box, but some are under the hood.","For glove-box style: open the glove box, press the sides inward to release it, then lower it fully to expose the filter housing.","Slide out the old filter — note the airflow direction arrow before removing it.","Insert the new filter with the arrow pointing in the same direction.","Close the housing and reinstall the glove box. Run the fan to confirm improved airflow."]'::jsonb,ARRAY['Vehicle-specific filter location','Glove box removal','Airflow direction'],'[{"name":"Cabin air filter (model-specific)","rent":null,"buy":"https://www.amazon.com/s?k=cabin%20air%20filter%20replacement&tag=oxsteed-20"}]'::jsonb,10,'published'),
('check-and-top-fluids','Check and Top Off Vehicle Fluids','car-care','Easy',20,FALSE,'Checking five fluids every month takes 20 minutes and catches problems before they become expensive repairs. Here''s the standard walkaround.','["Park on a level surface. Turn off the engine and wait 10 minutes for fluids to settle.","Engine oil: Pull the dipstick, wipe clean, reinsert fully, pull again. Oil should be between the MIN and MAX marks.","Coolant: Check the translucent overflow reservoir level (never open the radiator cap on a hot engine). Top up with 50/50 pre-mixed coolant if low.","Brake fluid: Check the reservoir on top of the master cylinder. Should be between MIN and MAX. If consistently low, suspect a leak.","Windshield washer fluid: Top off as needed. Power steering fluid (if not electric): check the reservoir under the hood and top to MAX."]'::jsonb,ARRAY['Dipstick reading','Reservoir identification','When to escalate to a mechanic'],'[{"name":"Funnel","rent":null,"buy":"https://www.amazon.com/s?k=funnel%20set%20automotive&tag=oxsteed-20"},{"name":"50/50 pre-mixed coolant","rent":null,"buy":"https://www.amazon.com/s?k=50%2050%20premixed%20coolant%20antifreeze&tag=oxsteed-20"},{"name":"Windshield washer fluid","rent":null,"buy":"https://www.amazon.com/s?k=windshield%20washer%20fluid&tag=oxsteed-20"}]'::jsonb,10,'published'),
('mulch-garden-bed','Mulch a Garden Bed','landscaping','Easy',120,FALSE,'Mulch suppresses weeds, retains moisture, and regulates soil temperature — 3 to 4 inches is the sweet spot.','["Clear the bed of weeds, pulling from the root. Cutting them leaves regrowth.","Edge the bed with a flat spade to create a clean border.","Optionally lay cardboard or landscape fabric for extra weed suppression.","Spread mulch to a 3–4 inch even depth using a rake.","Keep mulch 2–3 inches away from plant stems and tree trunks to prevent rot."]'::jsonb,ARRAY['Weed removal','Bed edging','Mulch depth control'],'[{"name":"Flat spade for edging","rent":"/tool-rentals?category=landscaping","buy":"https://www.amazon.com/s?k=flat%20spade%20edger&tag=oxsteed-20"},{"name":"Garden rake","rent":"/tool-rentals?category=landscaping","buy":"https://www.amazon.com/s?k=garden%20rake&tag=oxsteed-20"},{"name":"Wheelbarrow","rent":"/tool-rentals?category=landscaping","buy":null},{"name":"Bagged or bulk mulch","rent":null,"buy":"https://www.amazon.com/s?k=garden%20mulch%20bag&tag=oxsteed-20"}]'::jsonb,10,'published'),
('plant-a-tree','Plant a Tree Properly','landscaping','Medium',90,FALSE,'Most trees die within 3 years of planting from one mistake: being planted too deep. Here''s how to give a tree the best possible start.','["Call 811 (US) or your local utility service before digging to mark underground lines.","Dig the hole 2–3× as wide as the root ball but no deeper than the root ball height. Planting too deep is the #1 cause of tree failure.","Place the tree so the root flare (where the trunk widens at the base) sits at or slightly above grade.","Backfill with native soil (no amendments needed for most trees). Tamp gently to eliminate air pockets.","Build a 3–4\" mulch ring extending to the drip line — keep mulch away from the trunk. Water deeply at planting and weekly for the first year."]'::jsonb,ARRAY['Utility line awareness','Root flare identification','Proper hole depth','Post-plant watering schedule'],'[{"name":"Digging spade","rent":"/tool-rentals?category=landscaping","buy":"https://www.amazon.com/s?k=digging%20spade%20shovel&tag=oxsteed-20"},{"name":"Wheelbarrow","rent":"/tool-rentals?category=landscaping","buy":null},{"name":"Garden hose + soaker","rent":null,"buy":"https://www.amazon.com/s?k=soaker%20hose%20garden&tag=oxsteed-20"}]'::jsonb,25,'published'),
('install-drip-irrigation','Install a Simple Drip Irrigation System','landscaping','Medium',120,FALSE,'Drip irrigation delivers water directly to roots, cutting outdoor water use by 30–50%. A basic system for a garden bed takes an afternoon and uses standard hose fittings.','["Sketch the bed layout and count the number of plants to be irrigated. Choose emitter flow rates (0.5–1 GPH for most plants).","Install a hose-thread timer and backflow preventer at the spigot. Add a pressure regulator and filter.","Run the main 1/2\" poly tubing from the spigot to the bed using stakes.","Punch holes in the main line with a hole punch. Insert barbed fittings and connect 1/4\" drip lines to each plant.","Run the system and check all emitters for flow. Adjust timer to run 30–60 minutes per zone every 1–2 days."]'::jsonb,ARRAY['Drip system layout','Emitter selection','Timer programming'],'[{"name":"Drip irrigation starter kit","rent":null,"buy":"https://www.amazon.com/s?k=drip%20irrigation%20system%20starter%20kit&tag=oxsteed-20"},{"name":"Hole punch for poly tubing","rent":null,"buy":"https://www.amazon.com/s?k=drip%20irrigation%20hole%20punch%20tool&tag=oxsteed-20"},{"name":"Hose timer","rent":null,"buy":"https://www.amazon.com/s?k=hose%20timer%20programmable&tag=oxsteed-20"}]'::jsonb,25,'published'),
('build-raised-garden-bed','Build a Raised Garden Bed','landscaping','Medium',180,FALSE,'A 4×8 raised bed can produce more food per square foot than a ground garden, while solving drainage, soil quality, and back-strain problems at once.','["Choose a spot with 6–8 hours of direct sun. Mark the outline: 4 ft × 8 ft is the standard size (reachable from all sides).","Cut 2×10 or 2×12 cedar or redwood boards to length (two 8-ft and two 4-ft pieces). Assemble the frame with 3\" wood screws at each corner.","Set the frame in place on level ground. Staple hardware cloth to the bottom of the frame to block burrowing pests (optional but recommended).","Fill the bed with a 60/40 mixture of topsoil and compost to within 1–2 inches of the top.","Water thoroughly and let the soil settle for 24 hours before planting."]'::jsonb,ARRAY['Lumber cutting','Frame assembly','Soil mix preparation'],'[{"name":"Circular saw or miter saw","rent":"/tool-rentals?category=power-tools","buy":null},{"name":"Drill + 3\" deck screws","rent":"/tool-rentals?category=power-tools","buy":"https://www.amazon.com/s?k=3%20inch%20deck%20screws%20box&tag=oxsteed-20"},{"name":"Level","rent":null,"buy":"https://www.amazon.com/s?k=24%20inch%20level&tag=oxsteed-20"},{"name":"Hardware cloth + staple gun (optional)","rent":null,"buy":"https://www.amazon.com/s?k=hardware%20cloth%201%2F4%20inch%20roll&tag=oxsteed-20"}]'::jsonb,25,'published'),
('sharpen-mower-blade','Sharpen a Lawn Mower Blade','landscaping','Easy',30,FALSE,'A dull mower blade tears grass instead of cutting it, leaving a ragged brown edge that stresses the lawn. Sharpening once a season (or every 25 hours of use) keeps cuts clean and the lawn healthy.','["Disconnect the spark plug wire before working near the blade. Tilt the mower on its side with the carburetor facing up — if the carburetor faces down, oil enters the air filter.","Use a wrench to remove the blade bolt (it''s reverse-threaded on some models — check your manual). Mark the bottom face of the blade with chalk so you remount it the right way.","Clamp the blade in a vise. Use a metal file or angle grinder to sharpen along the existing bevel angle (usually 30–45 degrees). Remove an equal amount from both ends to keep the blade balanced.","Test balance: hang the blade on a nail through the center hole. If one end dips, remove a little more metal from that end. An unbalanced blade causes vibration that damages the engine bearings.","Reinstall the blade — torque the bolt to spec (usually 35–50 ft-lbs for residential mowers). Reconnect the spark plug wire."]'::jsonb,ARRAY['Spark plug safety','Blade balancing','Bevel angle maintenance'],'[{"name":"Wrench set or socket set","rent":null,"buy":"https://www.amazon.com/s?k=combination%20wrench%20set%20metric%20standard&tag=oxsteed-20"},{"name":"Metal file or angle grinder","rent":null,"buy":"https://www.amazon.com/s?k=metal%20file%20set%20flat%20bastard&tag=oxsteed-20"},{"name":"Blade balancing tool","rent":null,"buy":"https://www.amazon.com/s?k=lawn%20mower%20blade%20balancer%20cone&tag=oxsteed-20"}]'::jsonb,10,'published'),
('lay-sod','Lay Sod for Instant Lawn','landscaping','Medium',180,FALSE,'Sod gives you an instant lawn rather than waiting for seed to germinate. The work is physical, but the technique is straightforward: prepare soil properly, lay tightly, water immediately and consistently for two weeks.','["Measure the area in square feet. Order 5–10% more sod than your measurement to account for cuts around edges.","Till or loosen the soil 4–6 inches deep. Remove rocks, old roots, and debris. Grade the area so it slopes slightly away from the house (1\" per 10 feet).","Apply starter fertilizer per package directions and rake it in. Lightly water the soil before laying — it should be moist, not muddy.","Lay the first row along a straight edge (a driveway or walkway). Stagger joints like brick — start every other row with a half piece. Butt pieces tightly together with no gaps and no overlaps.","Water the sod immediately after laying. For the first two weeks, keep the sod consistently moist — twice daily in hot weather. After roots establish (lift a corner to check for resistance), reduce to deep infrequent watering."]'::jsonb,ARRAY['Soil grading','Staggered joint layout','Sod establishment watering'],'[{"name":"Sod cutter or sharp spade","rent":"/tool-rentals?category=landscaping","buy":null},{"name":"Lawn roller","rent":"/tool-rentals?category=landscaping","buy":null},{"name":"Landscape rake","rent":null,"buy":"https://www.amazon.com/s?k=landscape%20rake%20soil%20leveling&tag=oxsteed-20"}]'::jsonb,25,'published'),
('caulk-bathtub','Recaulk a Bathtub','maintenance','Easy',30,FALSE,'Cracked or moldy caulk lets water into the wall. Removing the old bead and applying a fresh one is quick and worth doing every few years.','["Use a caulk remover tool or utility knife to cut and pull out all the old caulk.","Clean the joint thoroughly with rubbing alcohol. Let it dry completely — even overnight.","Fill the tub with water before caulking; this pre-stresses the joint so it won''t crack in use.","Apply a thin, continuous bead of tub-and-tile silicone caulk along the joint.","Wet your finger and smooth the bead in one pass. Remove tape immediately. Let cure 24–48 hours before use."]'::jsonb,ARRAY['Caulk removal','Surface prep','Bead application','Wet smoothing'],'[{"name":"Caulk remover tool","rent":null,"buy":"https://www.amazon.com/s?k=caulk%20remover%20tool&tag=oxsteed-20"},{"name":"Tub-and-tile silicone caulk","rent":null,"buy":"https://www.amazon.com/s?k=tub%20tile%20silicone%20caulk%20white&tag=oxsteed-20"},{"name":"Rubbing alcohol","rent":null,"buy":"https://www.amazon.com/s?k=isopropyl%20alcohol%2091%25&tag=oxsteed-20"}]'::jsonb,10,'published'),
('clean-gutters','Clean Your Gutters','maintenance','Easy',60,FALSE,'Clogged gutters cause fascia rot, foundation water intrusion, and ice dams. A once-a-year clean takes an hour and prevents thousands in repairs.','["Set up a stable ladder at the corner of the house. Never lean a ladder against a gutter.","Starting at the downspout end, scoop out debris by hand into a bucket. Work toward the high end.","Flush the gutter with a garden hose, directing water toward the downspout.","Check that the downspout flows freely — feed the hose into the top. If clogged, use a plumber''s snake or a downspout cleaning wand.","Check for low spots or sagging gutters where water pools. Re-fasten any loose hanger brackets."]'::jsonb,ARRAY['Ladder safety','Downspout clearing','Gutter slope assessment'],'[{"name":"Extension ladder","rent":"/tool-rentals?category=access","buy":null},{"name":"Garden hose with spray nozzle","rent":null,"buy":"https://www.amazon.com/s?k=garden%20hose%20spray%20nozzle&tag=oxsteed-20"},{"name":"Bucket and hooks","rent":null,"buy":"https://www.amazon.com/s?k=bucket%20hook%20ladder&tag=oxsteed-20"},{"name":"Gutter scoop","rent":null,"buy":"https://www.amazon.com/s?k=gutter%20cleaning%20scoop&tag=oxsteed-20"}]'::jsonb,10,'published'),
('weatherstrip-exterior-door','Weatherstrip an Exterior Door','maintenance','Easy',45,FALSE,'A drafty door can be responsible for 10–20% of a home''s heating and cooling loss. Replacing weatherstripping costs under $20 and takes less than an hour.','["Close the door and hold a lit stick of incense along all edges — smoke wavering indicates air infiltration.","Remove the old weatherstripping by pulling it off or unscrewing it. Note the type: V-strip, foam tape, or door sweep.","Cut the new weatherstrip to length with scissors or a utility knife.","For V-strip: nail or peel-and-stick along the door stop with the open end of the V facing outward.","For the door sweep: cut to door width, align it so it just contacts the threshold, and screw in place."]'::jsonb,ARRAY['Air infiltration testing','Weatherstrip type identification','Door sweep installation'],'[{"name":"Door weatherstrip kit (includes V-strip and door sweep)","rent":null,"buy":"https://www.amazon.com/s?k=door%20weatherstripping%20kit&tag=oxsteed-20"},{"name":"Scissors or utility knife","rent":null,"buy":"https://www.amazon.com/s?k=utility%20knife&tag=oxsteed-20"},{"name":"Phillips screwdriver","rent":null,"buy":"https://www.amazon.com/s?k=screwdriver%20set&tag=oxsteed-20"}]'::jsonb,10,'published'),
('power-wash-driveway','Power Wash a Driveway or Patio','maintenance','Easy',90,FALSE,'Power washing removes years of tire marks, oil stains, mildew, and grime in one pass. The key is using the right nozzle — the wrong one etches concrete.','["Clear the area of furniture, cars, and potted plants. Sweep off loose debris first.","Connect the pressure washer to a water supply and turn on before starting the engine/motor.","For concrete driveways, start with a 25-degree (green) nozzle at 2,500–3,000 PSI. For wood decks, use a 40-degree (white) nozzle.","Work in overlapping passes moving away from the house. Hold the nozzle 12–18 inches from the surface.","For oil stains: apply a degreaser, let it dwell 5 minutes, then wash with the 25-degree nozzle."]'::jsonb,ARRAY['Nozzle selection','PSI safety','Dwell time for degreasers'],'[{"name":"Pressure washer (2,500–3,000 PSI)","rent":"/tool-rentals?category=cleaning","buy":null},{"name":"Concrete/driveway degreaser","rent":null,"buy":"https://www.amazon.com/s?k=concrete%20driveway%20degreaser%20cleaner&tag=oxsteed-20"},{"name":"Safety goggles","rent":null,"buy":"https://www.amazon.com/s?k=safety%20goggles%20protective%20eyewear&tag=oxsteed-20"}]'::jsonb,10,'published'),
('re-grout-tile','Remove and Re-Grout Tile','maintenance','Medium',120,FALSE,'Cracked or stained grout lets water into the substrate, eventually damaging the wall or subfloor. Removing old grout and applying fresh grout is straightforward with an oscillating tool and the right grout type.','["Use a grout saw or oscillating multi-tool with a grout removal blade to cut out the old grout. Cut to at least half the grout joint depth. Vacuum out all debris.","Clean the joint area with a stiff brush and a tile cleaner. Let dry completely — new grout will not bond to wet or dirty joints.","Mix the grout to a peanut butter consistency (for sanded grout) or a thick paste (unsanded for joints under 1/8\"). Let it slake for 10 minutes before using.","Apply grout with a rubber float, pressing diagonally across the joints to pack them fully. Remove excess from the tile surface immediately with the float edge.","After 15–20 minutes, clean the haze with a damp sponge in circular motions, rinsing frequently. After 24 hours, apply grout sealer to protect from staining."]'::jsonb,ARRAY['Oscillating tool use','Grout mixing','Float technique','Sponge haze removal'],'[{"name":"Oscillating multi-tool + grout blade","rent":"/tool-rentals?category=maintenance","buy":null},{"name":"Rubber grout float","rent":null,"buy":"https://www.amazon.com/s?k=rubber%20grout%20float%20tile&tag=oxsteed-20"},{"name":"Sanded grout (for joints 1/8\"+ wide)","rent":null,"buy":"https://www.amazon.com/s?k=sanded%20tile%20grout%20unsanded%20grout&tag=oxsteed-20"},{"name":"Grout sealer","rent":null,"buy":"https://www.amazon.com/s?k=tile%20grout%20sealer%20penetrating&tag=oxsteed-20"}]'::jsonb,25,'published'),
('fix-sticking-door','Fix a Sticking or Binding Door','maintenance','Easy',30,FALSE,'A door that sticks or rubs is usually caused by swelling wood, a shifted frame, or loose hinges. Identifying which one is causing the problem takes 3 minutes and determines whether the fix is a screwdriver or a plane.','["Watch where the door binds: does it rub at the top corner (opposite hinge side), along the latch edge, or at the bottom? The location tells you the cause.","Check the hinges first — tighten all screws. If a screw spins freely, the hole is stripped. Fill with a wooden toothpick and wood glue, let dry, then re-drive the screw.","Close the door and look for gaps: a gap at the top-hinge corner with rubbing at the bottom-latch corner means the top hinge needs shimming. Cardboard under the hinge leaf shifts the door.","If the door rubs along its full latch edge, it has swollen with humidity. Mark the binding point with a pencil on a closed door. Open the door and use a hand plane or belt sander to remove material from the marked area.","Prime and paint any bare wood immediately after planing — raw wood absorbs moisture and the problem returns."]'::jsonb,ARRAY['Hinge diagnosis','Screw hole repair','Planing technique','Shimming'],'[{"name":"Screwdrivers","rent":null,"buy":"https://www.amazon.com/s?k=screwdriver%20set%20flathead%20phillips&tag=oxsteed-20"},{"name":"Hand plane or belt sander","rent":"/tool-rentals?category=carpentry","buy":null},{"name":"Toothpicks + wood glue (for stripped holes)","rent":null,"buy":"https://www.amazon.com/s?k=wood%20glue%20carpenter%20wood%20filler&tag=oxsteed-20"}]'::jsonb,10,'published'),
('inspect-investment-property','How to Inspect an Investment Property','management','Medium',90,TRUE,'A thorough walkthrough before you close identifies deferred maintenance, hidden defects, and real repair costs — the numbers that determine whether a deal works. Here''s how to walk a property like a professional.','["Bring a checklist, a flashlight, a screwdriver, and a phone for photos. Start outside: roof condition, gutters, grading (slope away from foundation?), caulk at windows and doors.","Check the foundation for cracks. Hairline vertical cracks are common; horizontal cracks or stair-step cracks in brick indicate structural movement — flag for an engineer.","Inside: test every outlet (bring a plug-in tester), every faucet (run hot and cold, check under the sink for leak evidence), every door and window (should operate and latch freely).","In kitchens and baths: look under sinks for water stains, soft cabinet floors, and drain odor. Run the dishwasher if possible. Check grout and caulk in showers.","In the mechanical room: note HVAC age, water heater age, and electrical panel brand. Zinsco and Federal Pacific panels are known fire hazards — flag for replacement in your budget.","Write down every issue with a photo. Group findings into: immediate safety issues, code violations, cosmetic items, and deferred maintenance. Translate to a cost estimate before finalizing your offer."]'::jsonb,ARRAY['Structural assessment','Mechanical system age estimation','Repair cost categorization'],'[{"name":"Outlet plug tester","rent":null,"buy":"https://www.amazon.com/s?k=outlet%20receptacle%20tester%20circuit&tag=oxsteed-20"},{"name":"Flashlight","rent":null,"buy":"https://www.amazon.com/s?k=led%20flashlight%20bright%20inspection&tag=oxsteed-20"},{"name":"Moisture meter","rent":null,"buy":"https://www.amazon.com/s?k=moisture%20meter%20wood%20drywall&tag=oxsteed-20"}]'::jsonb,25,'published'),
('estimate-repair-costs','How to Estimate Repair and Renovation Costs','management','Medium',60,FALSE,'Accurate repair cost estimates are the difference between a profitable deal and an expensive mistake. This guide covers the mental model and reference benchmarks that experienced investors use before committing to a number.','["Categorize repairs into three buckets: cosmetic (paint, carpet, fixtures), functional (HVAC, roof, plumbing, electrical), and structural (foundation, load-bearing walls). Each bucket has a different cost range and timeline.","Use cost-per-square-foot benchmarks as starting points: full gut renovation $80–150/sqft, kitchen remodel $15,000–40,000, bathroom $6,000–15,000, roof replacement $8,000–18,000, HVAC system $4,000–10,000.","Get at least three contractor quotes for any item over $2,000. Always ask for a written scope of work — \"I''ll fix the plumbing\" is not a scope. \"Replace all galvanized supply lines with PEX, includes shutoffs\" is.","Add a 20% contingency on every estimate. First-time renovators consistently underestimate by 25–40% because they miss scope creep, permit costs, and post-opening surprises.","Track actual spend versus estimate on every project and build your own local benchmark database over time. Your estimates improve with every project — and local costs matter more than national averages."]'::jsonb,ARRAY['Cost categorization','Contractor scope vetting','Contingency budgeting'],'[{"name":"HomeAdvisor or Angi cost guides (free online)","rent":null,"buy":null},{"name":"Renovation cost estimating software (optional)","rent":null,"buy":null}]'::jsonb,25,'published'),
('build-preventive-maintenance-schedule','Build a Property Preventive Maintenance Schedule','management','Easy',45,FALSE,'Preventive maintenance costs cents on the dollar compared to reactive repair. A simple annual schedule for each property turns chaos into a predictable rhythm — and protects asset value.','["List every major system in each property: HVAC, water heater, roof, gutters, exterior caulk, smoke detectors, fire extinguishers, plumbing shutoffs, appliances.","Assign a maintenance interval to each item based on manufacturer recommendations and local climate. HVAC filter: monthly or quarterly. Gutters: twice/year. Water heater flush: annually. Roof inspection: annually.","Build a 12-month calendar. Group items by season: spring (HVAC service, gutter cleaning, exterior caulk inspection), summer (pest inspection, AC checkup), fall (weatherstripping, dryer vent clean), winter (pipe insulation check, smoke detector test).","Assign each task to a responsible party: self, on-site manager, or contracted vendor. Confirm the vendor in advance so you''re not scrambling when the task is due.","Document completion with a date and any findings. This record is your maintenance history — it supports warranty claims, insurance disputes, and eventually, sale documentation."]'::jsonb,ARRAY['Maintenance scheduling','Vendor management','Documentation practices'],'[{"name":"Spreadsheet or property management software","rent":null,"buy":null},{"name":"Shared calendar (Google Calendar, Notion, etc.)","rent":null,"buy":null}]'::jsonb,10,'published'),
('write-a-work-order','Write a Clear Maintenance Work Order','management','Easy',20,FALSE,'A clear work order protects both the property owner and the contractor. Vague instructions produce vague results — and disputes. Here''s the anatomy of a work order that gets the job done right.','["Property and location: full address, unit number, and point-of-contact name and phone number.","Problem description: describe the issue in observable terms, not your diagnosis. \"Dripping sound under kitchen sink since Monday, water stains on cabinet floor\" — not \"leaky pipe.\"","Scope of work: if you know what you want done, say it. If you don''t, say \"assess and provide a written quote before proceeding.\" Don''t leave the scope open-ended if you''re authorizing work.","Access instructions: who has the key, when can the contractor enter, is the tenant home, are there pets.","Authorization limit: the maximum dollar amount the contractor is authorized to spend without calling you first. This prevents a $300 job becoming a $1,200 invoice.","Document completion: require a brief written summary of what was done and any follow-up items, plus photos if applicable."]'::jsonb,ARRAY['Problem description','Scope definition','Authorization limits'],'[{"name":"Work order template (spreadsheet, Word doc, or property management software)","rent":null,"buy":null}]'::jsonb,10,'published'),
('diagnose-plumbing-remotely','Diagnose Common Plumbing Problems Remotely','plumbing','Easy',20,FALSE,'Most plumbing calls fall into a small set of recurring categories. Knowing which questions to ask — before you dispatch or pick up a wrench — saves time, money, and unnecessary service calls.','["Symptom: dripping sound. Ask: dripping from a faucet, from a pipe, or from under the sink? Faucet drip → worn washer or cartridge. Under-sink drip → drain connection or supply shut-off valve. Pipe drip → locate the pipe section and shut off water.","Symptom: slow drain. Ask: one drain or multiple? One drain → likely clog local to that fixture. Multiple drains slow → main line blockage. Drain completely stopped + toilet bubbling → call a plumber.","Symptom: toilet running. Ask: does it stop eventually, or run continuously? Running that stops → fill valve or flapper. Continuous running with water audible in bowl → flush valve. Try jiggling the handle — if it helps, flapper chain is the issue.","Symptom: no hot water. Ask: gas or electric? When did it stop? Any pilot light visible? If electric: check the breaker first. If gas with pilot out: relight per the label. If pilot is lit but no hot water after 30 min → thermostat or element.","Symptom: low water pressure. Ask: one fixture or whole house? One fixture → aerator clog (unscrew and clean). Multiple fixtures → pressure regulator or municipal supply issue. Sudden whole-house drop → check your main shutoff."]'::jsonb,ARRAY['Symptom-to-cause mapping','Triage questioning','Escalation criteria'],'[{"name":"Flashlight (for under-sink inspection)","rent":null,"buy":"https://www.amazon.com/s?k=led%20flashlight%20bright%20inspection&tag=oxsteed-20"},{"name":"Phone camera (for documenting and sharing the problem)","rent":null,"buy":null}]'::jsonb,10,'published'),
('diagnose-electrical-remotely','Diagnose Common Electrical Problems Remotely','electrical','Easy',20,FALSE,'Electrical symptoms that seem mysterious usually have a logical cause. Knowing what questions to ask — and when to stop troubleshooting and call an electrician — is the most valuable electrical skill most people never learn.','["Symptom: outlet not working. First check: is it a GFCI outlet? Press the RESET button (common in bathrooms, kitchens, garages). Still dead → check the breaker panel. Breaker tripped → reset it. Still dead → outlet may need replacement (call a helper).","Symptom: breaker keeps tripping. Ask: which circuits? A single circuit that trips repeatedly under load → overloaded circuit (too many devices). A breaker that trips immediately when reset → short circuit or faulty device. Unplug everything on the circuit and reset — if it holds, add devices back one at a time.","Symptom: lights flickering. Ask: one light or the whole house? One light → loose bulb or failing fixture. One room → loose wire at the switch or fixture. Whole house → contact the utility company first (not an electrician). Flickering with buzzing → call an electrician.","Symptom: burning smell near an outlet or panel. Action: turn off the circuit at the panel immediately and call a licensed electrician. Do not troubleshoot a burning smell — this is a fire risk.","Symptom: no power in part of the house. Check: is it an outage or is it the panel? Look at the panel — any tripped breakers (middle position)? Reset them. Still no power → check with neighbors and call the utility."]'::jsonb,ARRAY['GFCI reset procedure','Breaker identification','Escalation criteria for safety'],'[{"name":"Outlet plug tester","rent":null,"buy":"https://www.amazon.com/s?k=outlet%20receptacle%20tester%20circuit&tag=oxsteed-20"},{"name":"Flashlight","rent":null,"buy":"https://www.amazon.com/s?k=led%20flashlight%20bright%20inspection&tag=oxsteed-20"}]'::jsonb,10,'published'),
('post-your-first-job','Post Your First Job on OxSteed','customer','Easy',15,TRUE,'A well-written job post attracts better helpers and faster responses. The difference between a vague post and a specific one is often hours of waiting versus bids arriving within minutes.','["Open the app and tap ''Post a Job.'' Choose the category that best fits your task — if you''re unsure, pick the closest one; you can clarify in the description.","Write a clear title. ''Leaky kitchen faucet — drips at the handle'' is better than ''plumbing issue.'' Specific titles attract helpers with the right skills.","In the description, explain what''s broken, what you''ve already tried, and any access details (e.g., ''third-floor unit, stairs only, dog inside''). More context means fewer back-and-forth questions.","Upload 2–3 photos of the problem area. Photos cut quote time in half — helpers can see the scope before they arrive.","Set your preferred timing: ASAP, this week, or flexible. Choose a realistic budget range if you have one — it filters out poor fits and speeds up serious bids."]'::jsonb,ARRAY['Job description writing','Photo documentation','Budget setting'],'[]'::jsonb,10,'published'),
('evaluate-helper-bids','How to Evaluate Helper Bids','customer','Easy',20,FALSE,'Multiple bids can feel overwhelming. Here''s a simple framework for choosing the right helper — not just the cheapest one.','["Compare bids on three things: price, response quality, and profile strength. A helper who asks clarifying questions before quoting is more reliable than one who fires off the lowest number immediately.","Check their OxSteed profile: completed jobs, review count, star rating, and any verified badges (ID-verified, background-checked). A verified badge means they''ve passed our identity check.","Read the most recent 3–5 reviews. Look for patterns — not just the star average. ''Always on time'' repeated five times is more meaningful than one glowing paragraph.","Message the top two or three helpers. Ask: ''Have you done this type of job before?'' and ''When can you start?'' How quickly and clearly they respond tells you a lot about how they''ll communicate on the job.","Award the job to your preferred helper. If you''re between two, choose the one with more reviews — they''ve been vetted by the community more times."]'::jsonb,ARRAY['Bid comparison','Profile evaluation','Helper vetting'],'[]'::jsonb,10,'published'),
('write-great-job-description','Write a Job Description That Gets Fast Bids','customer','Easy',20,FALSE,'The quality of your job description determines the quality of the bids you receive. Vague posts attract guesswork bids; specific posts attract pros who know exactly what they''re getting into.','["Lead with the problem, not the solution. ''Hot water heater making a popping noise for three days'' is more useful than ''I need a plumber.'' Describe symptoms, not diagnoses.","Add dimensions and quantities where relevant. ''A 10×12 room'' or ''about 40 linear feet of baseboard'' lets helpers estimate material and time accurately.","Note access constraints. Parking, building access hours, pets, whether you''ll be home, which floor — anything that affects the helper''s logistics.","State your timeline explicitly: ''needs to be done before next Saturday'' or ''flexible, just want it done right.'' Urgency affects pricing — know that going in.","Include your budget range if you have one. ''Looking to spend around $150–200'' filters serious bids quickly and saves everyone time."]'::jsonb,ARRAY['Scope description','Context-setting','Timeline communication'],'[]'::jsonb,10,'published'),
('shop-the-marketplace','Shop the OxSteed Marketplace','customer','Easy',15,FALSE,'The OxSteed marketplace lists pre-priced services from local helpers — no bidding needed. Perfect for routine tasks where you already know what you need.','["Browse marketplace listings by category: cleaning, moving, landscaping, handyperson, and more. Each listing shows a flat rate or hourly price, the helper''s rating, and their typical response time.","Tap any listing to read the full service description. Check what''s included and what''s not — scope varies between providers.","Use the filters to narrow by distance, availability date, and minimum review count. Helpers who are available this week appear first.","Book directly from the listing. You''ll pay through OxSteed''s secure payment system — funds are held and released only after you confirm the job is complete.","After the job, leave a review. Reviews are the marketplace''s quality signal — they help other customers and reward helpers who do good work."]'::jsonb,ARRAY['Marketplace navigation','Secure booking','Review etiquette'],'[]'::jsonb,10,'published'),
('resolve-a-dispute','How to Resolve a Dispute with a Helper','customer','Easy',30,FALSE,'Most issues are resolved directly between customer and helper. When that doesn''t work, OxSteed''s support team can step in. Here''s how to handle it either way.','["Start with the helper directly. Message them through the app and describe the issue clearly: what was agreed, what happened, and what resolution you''re looking for. Most problems end here.","If the helper doesn''t respond within 24 hours or you can''t reach agreement, open a dispute through the job''s detail page. Tap ''Get Help with This Job'' and follow the prompts.","Document everything before you escalate: photos of the work, screenshots of your messages, and a summary of the original job post. The more specific you are, the faster support can act.","OxSteed holds payment in escrow until you confirm completion. If you haven''t released payment yet, you can flag the job as incomplete — this pauses the release and triggers a review.","For damaged property, report it immediately. OxSteed''s helper protection policy covers documented accidental damage up to the platform limit. Keep any damaged items for inspection."]'::jsonb,ARRAY['Direct resolution','Dispute escalation','Documentation for claims'],'[]'::jsonb,10,'published'),
('hire-a-recurring-helper','Set Up Recurring Help with One Helper','customer','Easy',20,FALSE,'Found a helper you trust? Setting up a recurring arrangement through OxSteed keeps the relationship official, keeps payments protected, and builds their reputation.','["After a successful job, message the helper and ask if they offer recurring work (weekly lawn care, bi-weekly cleaning, monthly handyperson visits, etc.).","Create a new job post for the recurring service. In the description, specify the frequency, scope of each visit, and access details. Invite the helper directly from their profile.","Use OxSteed''s recurring booking feature (if available in your area) to pre-schedule and auto-pay. This locks in availability and removes the friction of re-booking each time.","After the first few visits, check in: is the scope still right? Adjust the job post if the helper''s role grows or changes.","Leave a review after the first month. Recurring customers who review consistently help their helpers build a reputation that attracts more work — it''s a small thing that pays them back significantly."]'::jsonb,ARRAY['Recurring booking','Scope management','Long-term helper relationships'],'[]'::jsonb,10,'published'),
('write-a-winning-bid','Write a Bid That Wins Jobs','helper','Easy',20,TRUE,'Most bids are ignored because they''re generic. A bid that speaks directly to the customer''s situation — and shows you actually read their post — wins jobs even when your price isn''t the lowest.','["Read the job post twice before writing anything. Note the specific problem, any urgency signals (''before the weekend''), and any access or logistics details they mentioned.","Open your bid with a direct acknowledgment of their specific issue: ''I''ve fixed dozens of leaky kitchen faucets — usually a worn cartridge or O-ring, which I carry in my truck.'' This takes 10 seconds and signals expertise.","Give a price range, not a single number, until you''ve seen the job in person. ''Usually $80–120 depending on the part'' is honest and sets expectations correctly.","State your availability specifically: ''I''m free Tuesday after 2pm or Thursday morning.'' Specific availability is faster to act on than ''I can work with your schedule.''","End with a brief relevant credential: number of jobs completed, a skill certificate, or a specific type of job you specialize in. One sentence. Don''t over-sell."]'::jsonb,ARRAY['Bid writing','Price framing','Availability communication'],'[]'::jsonb,10,'published'),
('build-your-reputation','Build Your OxSteed Reputation Fast','helper','Easy',30,FALSE,'Your reputation is your most valuable asset on OxSteed. New helpers who focus on reviews and profile quality in the first 30 days earn significantly more in month two.','["Complete your profile fully before bidding on anything: professional photo, service description, categories you cover, and your service area. Incomplete profiles lose to complete ones every time.","Bid on 5–10 small, high-success jobs first (under $100, simple scope). Quick wins early build your review count faster than fewer large jobs.","After every completed job, message the customer: ''Thanks for choosing me — if everything looks good, I''d really appreciate a review.'' Most customers are happy to leave one; they just need the nudge.","Deliver punctually and communicate proactively. Message when you''re 20 minutes away. If you hit a snag, tell them before they have to ask. Communication is the #1 factor in 5-star reviews.","Ask verified helpers in your area to co-work on larger jobs early on. You gain experience, they gain capacity, and customers see a team they can trust."]'::jsonb,ARRAY['Profile optimization','Review solicitation','Customer communication'],'[]'::jsonb,10,'published'),
('set-your-service-rates','Set Your Service Rates Competitively','helper','Medium',30,FALSE,'Pricing too low burns you out. Pricing too high loses jobs. Here''s how to find the right range for your market and your skill level.','["Research what other helpers in your area charge for the same services. Browse OxSteed marketplace listings and local Craigslist gigs — this gives you the real market floor.","Calculate your true cost per hour: vehicle cost (IRS rate is ~67¢/mile), tools amortized over their lifespan, supplies, and the OxSteed service fee. Your rate must exceed this to be profitable.","Set a base hourly rate and per-job flat rates for common tasks. Flat rates are easier to sell (''$85 to hang a ceiling fan'') but require accurate time estimates — track every job until you know yours.","Price your first 10 jobs slightly below your target rate to build reviews. Then raise prices by $10–15/hour as your rating improves. Customers with 50 reviews can charge 20–30% more than those with 5.","Offer a small-job minimum. Most helpers set a $60–80 minimum regardless of job size — this makes short trips profitable and discourages very small requests from eroding your time."]'::jsonb,ARRAY['Market research','Cost-plus pricing','Rate anchoring'],'[]'::jsonb,25,'published'),
('get-your-first-review','Get Your First 5-Star Review','helper','Easy',20,FALSE,'Your first review is the hardest. Zero reviews means customers don''t know what to expect. Here''s how to earn that first one decisively.','["Identify a job in your skill set with a clear, achievable outcome — something you can complete in under two hours. Bid on several of these simultaneously so you improve your odds of landing one quickly.","Over-prepare for the job. Bring every tool you might need, arrive 5 minutes early, and have a backup plan if the first approach doesn''t work.","During the job, narrate what you''re doing in plain language. ''The issue was a worn washer — I replaced it and also tightened the packing nut so it won''t drip again.'' Customers who understand what happened are more likely to leave a detailed review.","Before you leave, do a final walkthrough with the customer. Ask: ''Is everything looking good? Anything else you''d like me to check?'' This closes the loop and catches any concerns before they become a negative review.","Message them the same evening: ''Thanks again — if you have a moment, a review would really help me get started on OxSteed.'' A timely, personal ask works far better than a generic notification."]'::jsonb,ARRAY['Job preparation','Customer narration','Review timing'],'[]'::jsonb,10,'published'),
('create-a-service-package','Build a Packaged Service Offering','helper','Medium',30,FALSE,'Packages let you sell your most common work at a flat rate customers can book instantly — no bidding, no negotiation, just consistent income.','["Identify your three most commonly requested services. These become your core packages. Pick tasks you can complete within a predictable time window.","Bundle related tasks. ''Spring HVAC Tune-Up: filter replacement + condensate drain flush + thermostat check — $129'' is easier to sell than three separate line items.","Set a competitive flat rate. Calculate your target rate × expected hours, then add a 15% buffer for the occasional longer job. Round to a clean number.","Write the package description clearly: what''s included, what''s not, how long it typically takes, and any requirements (e.g., ''customer must provide filter size''). Clarity reduces disputes.","List the package on your OxSteed profile and marketplace. Promote it by linking to it in your bids: ''I also offer a complete spring HVAC tune-up package if you''re interested.''"]'::jsonb,ARRAY['Service bundling','Flat-rate pricing','Marketplace listing'],'[]'::jsonb,25,'published'),
('source-goods-for-a-job','Source Materials and Goods for a Job','logistics','Easy',30,TRUE,'Sourcing materials efficiently is the difference between a profitable job and one that eats your margin. Knowing where to buy, when to buy in bulk, and how to pass costs through correctly makes or breaks logistics work.','["Before purchasing, confirm the exact specification with the customer or job manager: dimensions, brand preferences, grade (residential vs commercial), and any local code requirements that restrict substitutions.","Check three sources before buying: your local supplier account (net-30 terms if you have them), a big-box store for same-day availability, and OxSteed''s supplier partnerships for pooled pricing on high-volume items.","For jobs over $200 in materials, request a written quote from your supplier. This protects you if prices change between quote and purchase, and gives you documentation for the customer invoice.","Buy to spec, not to convenience. The cheapest option that doesn''t meet the spec costs more in rework than the right part at full price. When in doubt, buy the correct item.","Track every material receipt with a photo. Log it in your job notes immediately. This feeds your invoice, protects against disputes, and builds your cost-per-job data over time."]'::jsonb,ARRAY['Spec confirmation','Supplier comparison','Receipt documentation'],'[]'::jsonb,10,'published'),
('join-a-pooled-order','Join a Pooled Order to Cut Supply Costs','logistics','Easy',20,FALSE,'OxSteed''s pooled ordering aggregates purchases from multiple helpers and businesses in your area to unlock contractor-tier pricing — typically 15–30% below retail on common materials.','["Open the Marketplace section and navigate to ''Pooled Orders.'' Browse active pools by category (lumber, PEX, electrical, paint, landscaping materials) and area.","Find a pool that matches your upcoming material needs. Review the minimum order quantity, the supplier, the delivery window, and the per-unit cost.","Add your quantity to the pool. You commit to your portion — if the pool hits the minimum before the deadline, the order places automatically and materials ship to the listed delivery point.","Coordinate pickup or delivery logistics. Pooled orders typically deliver to a central point (a warehouse or participating business). Arrange your pickup within the delivery window.","Track your savings in the app. Over time, the Pooled Orders dashboard shows cumulative savings vs. retail — this data is useful for your annual business cost review."]'::jsonb,ARRAY['Pool selection','Minimum order math','Pickup logistics'],'[]'::jsonb,10,'published'),
('track-freight-shipment','Track and Manage an Inbound Freight Shipment','logistics','Easy',15,FALSE,'Freight shipments behave differently from parcel deliveries. Knowing how to track, communicate, and receive LTL freight keeps your job on schedule and prevents costly missed deliveries.','["Get the PRO number from the shipper — this is the freight equivalent of a tracking number. Enter it on the carrier''s website to see real-time freight status.","Watch for ''Out for Delivery'' status, then call the carrier''s local terminal to schedule a delivery appointment. Most LTL shipments require a scheduled window — they will not just show up.","Arrange for adequate unloading resources. LTL drivers deliver to the tailgate only — you are responsible for moving freight from the truck to your location. Have a pallet jack or enough hands ready.","Inspect every pallet before signing the delivery receipt. Note any visible damage on the receipt as ''subject to inspection'' before the driver leaves. Signing clean releases the carrier from liability.","If damage is discovered after the driver leaves, file a freight claim within 5 business days. Photograph the damage and packaging thoroughly — claims require photo evidence."]'::jsonb,ARRAY['PRO number tracking','LTL appointment scheduling','Inspection and damage claims'],'[]'::jsonb,10,'published'),
('manage-last-mile-distribution','Run a Last-Mile Distribution Route','logistics','Medium',45,FALSE,'Last-mile distribution — moving goods from a hub to final delivery points — is where logistics costs pile up and where efficiency gains compound. Here''s how to run a route that maximizes stops per hour.','["Plan your route before you load the vehicle. Use route optimization software (Google Maps with multiple stops, or Circuit / OptimoRoute) to minimize backtracking. Sequence stops geographically, not by order of receipt.","Load the vehicle in reverse delivery order: the last stop goes in first, the first stop loads last. This avoids unloading and re-loading at every stop.","Confirm delivery addresses and contact numbers the day before. A bad address or unavailable recipient wastes more time than traffic. Text recipients their expected window.","At each stop: deliver promptly, get a signature or photo confirmation, and note any exceptions (no one home, access issue, damaged goods) in real time — not at the end of the day.","After the route, reconcile your delivery confirmations against the manifest. Flag any undelivered items and communicate next-step options (re-delivery, return, hold for pickup) to the dispatcher before the day closes."]'::jsonb,ARRAY['Route optimization','Vehicle loading sequence','Proof of delivery'],'[{"name":"Route optimization app (Circuit, OptimoRoute, or Google Maps)","rent":null,"buy":null},{"name":"Pallet jack (for heavy cargo)","rent":"/tool-rentals?category=logistics","buy":null}]'::jsonb,25,'published'),
('set-up-inventory-system','Set Up a Simple Inventory Tracking System','logistics','Medium',45,FALSE,'Knowing what you have, where it is, and when to reorder is the foundation of logistics efficiency. A simple system beats a complex one you don''t use.','["List every item type you need to track: categories, units of measure, supplier, lead time, and minimum reorder quantity. This becomes your item master.","Choose a tracking tool that matches your scale. A shared Google Sheet works for a small operation. Purpose-built tools like Sortly or inFlow work better when you have more than 50 SKUs.","Assign a location to every item and label that location. ''Shelf B3, bin 2'' is a location. ''The back room'' is not. Labels make cycle counting fast.","Set reorder points based on lead time and average weekly consumption. If a part takes 3 days to arrive and you use 5 per week, your reorder point is 15 (3 days × 5/day, plus safety stock).","Do a weekly cycle count on your fastest-moving 20% of items. Catching discrepancies weekly is far cheaper than discovering them monthly when you''re already short on a job."]'::jsonb,ARRAY['Item master setup','Reorder point calculation','Cycle counting'],'[{"name":"Barcode scanner (optional, for higher volume)","rent":null,"buy":"https://www.amazon.com/s?k=bluetooth+barcode+scanner+inventory&tag=oxsteed-20"},{"name":"Label maker","rent":null,"buy":"https://www.amazon.com/s?k=label+maker+dymo+brother&tag=oxsteed-20"}]'::jsonb,25,'published'),
('book-first-consulting-session','Book Your First Paid Consulting Session','consulting','Easy',20,TRUE,'Your first paid session is a proof of concept — for yourself as much as the client. Here''s how to structure it so you deliver real value and the client wants to come back.','["Define what a session includes before you sell it. ''60-minute strategy call + a written summary of recommendations within 24 hours'' is a product. An open-ended conversation is not.","Set a price that reflects your expertise, not your nervousness. Research what peers in your specialty charge — then price at or near the median. Underpricing signals low confidence, not value.","List your session on your OxSteed Consultant profile with a clear description, your specialties, and what a client will get out of a session. Include a photo and short bio.","When a client books, send a confirmation message with three questions to answer before the call: What specific challenge are you trying to solve? What have you already tried? What does success look like?","Run the session with a simple structure: 10 min to confirm context, 40 min of your expert input, 10 min to agree on next steps. Stick to time — it signals professionalism."]'::jsonb,ARRAY['Session scoping','Pricing strategy','Pre-session intake'],'[]'::jsonb,10,'published'),
('write-consulting-proposal','Write a Consulting Proposal That Closes','consulting','Medium',45,FALSE,'A proposal isn''t a quote — it''s a persuasion document. It shows the client you understand their problem, explains your approach, and makes it easy for them to say yes.','["Open with a problem statement, not your credentials. Mirror back what the client told you: ''You''re losing 20% of revenue between quote and close and want to fix that in Q3.'' This shows you listened.","Describe your approach in plain terms: what you''ll do, in what order, and why that sequence. Skip jargon. A decision-maker who doesn''t understand your method won''t approve it.","Outline deliverables explicitly. ''A 12-page process audit and a 90-day implementation roadmap'' is a deliverable. ''Strategic recommendations'' is not.","State your price as a total and break it into phases if the engagement is long. Offering a payment schedule tied to deliverable milestones reduces client risk — and objections.","Include a simple ''next step'' at the end: ''To proceed, reply YES to this proposal or schedule a 15-minute call to discuss questions.'' Remove friction from the decision."]'::jsonb,ARRAY['Problem framing','Deliverable definition','Closing mechanics'],'[]'::jsonb,25,'published'),
('onboard-a-business-client','Onboard a New Business Client','consulting','Medium',60,FALSE,'Good onboarding sets expectations, reduces miscommunication, and starts the relationship on a professional footing. A structured first week saves dozens of hours later.','["Send a welcome message within one hour of contract signing. Include: the agreed scope, your contact info, how you prefer to communicate (email, app, phone), and your expected response time.","Schedule a kickoff call within 48 hours. Agenda: confirm goals, review the timeline, agree on how decisions get made, and identify who has authority to approve your work.","Set up a shared workspace for the engagement: a shared folder, a project tracking board, or a dedicated channel. Everything goes there — no managing by email thread.","Document the client''s existing context in a brief: their team structure, current process, past attempts at solving this problem, and what they''ve already ruled out. This becomes your reference document.","Agree on a check-in cadence upfront: weekly status update, bi-weekly call, or monthly review. Put it on the calendar before the kickoff ends. Consistency builds trust faster than any single deliverable."]'::jsonb,ARRAY['Kickoff facilitation','Shared workspace setup','Check-in cadence'],'[]'::jsonb,25,'published'),
('price-your-consulting-services','Price Your Consulting Services','consulting','Medium',30,FALSE,'Consultants who price by the hour are leaving money on the table. Value-based pricing aligns your fee with the result you create — not the time it takes you.','["Calculate your baseline: what annual income do you need, divided by billable hours per year. If you need $120K and bill 1,000 hours, your floor is $120/hour. This is your minimum — not your price.","Research what peers in your specialty charge. LinkedIn, Contra, and Toptal have public rate data. Local market rates vary significantly — OxSteed''s Consultant section shows local session pricing.","For project work, estimate the value your work creates for the client, then price at 10–20% of that value. A consultant who helps a client save $50,000/year in operational waste can charge $5,000–10,000 for that project.","Offer three options: a single session, a short engagement (30 days), and a retainer. Tiered pricing anchors the retainer against the session and makes the middle option feel like good value.","Raise your rates by 15–20% every six months if you''re consistently booking. If clients never push back on your price, you''re too cheap."]'::jsonb,ARRAY['Baseline rate calculation','Value-based pricing','Tiered offer structure'],'[]'::jsonb,25,'published'),
('deliver-a-discovery-session','Run a Discovery Session That Converts to a Project','consulting','Medium',45,FALSE,'A discovery session is a paid diagnostic — and the gateway to larger engagements. Run it well and the next step sells itself.','["Charge for discovery. A free consultation devalues your time and attracts clients who aren''t serious. $150–300 for a structured 90-minute session is standard.","Prepare a discovery guide: 10–15 questions that help you understand the client''s situation, goals, constraints, and past attempts. Share the questions in advance so they come prepared.","During the session, diagnose before prescribing. Ask ''tell me more'' at least three times before offering any solution. Rushing to recommendations makes you look like a vendor, not an advisor.","At the end of the session, summarize what you heard in three bullet points and ask: ''Is this an accurate picture?'' Confirm alignment before you propose anything.","Follow up within 24 hours with a written summary and, if appropriate, a project proposal. The proposal should reference specific things the client said during discovery — this shows they were heard."]'::jsonb,ARRAY['Discovery questioning','Listening discipline','Proposal timing'],'[]'::jsonb,25,'published'),
('list-tools-for-rent','List Your Tools for Rent on OxSteed','tool-rental','Easy',20,TRUE,'Your idle tools can earn while they sit. Listing on OxSteed takes 15 minutes and puts your equipment in front of local helpers and DIYers who need it for a day.','["Go to your OxSteed profile and tap ''List a Tool.'' Select the category that matches your equipment: power tools, access equipment, landscaping, plumbing, etc.","Add a clear, specific title: ''Dewalt 20V Cordless Drill/Driver with 2 Batteries'' — not ''drill.'' Include the brand, model, and key specs.","Take 3–4 photos: the tool from the front, the side, any accessories included, and any existing wear or cosmetic damage. Documenting existing condition up front protects you from damage disputes.","Set your daily and weekly rental rate. Check what similar tools rent for in your area via equipment rental chains like Home Depot or Sunbelt — price at 70–85% of their daily rate to be competitive.","Write brief rental terms: deposit required, what''s included, pickup/dropoff location, and any restrictions. Clear terms prevent misunderstandings."]'::jsonb,ARRAY['Tool listing','Condition documentation','Rate setting'],'[]'::jsonb,10,'published'),
('price-tool-rentals','Price Your Tool Rentals for Maximum Earnings','tool-rental','Easy',20,FALSE,'Rental pricing is a balance between utilization and return on investment. Price too high and tools sit idle. Price too low and you''re subsidizing other people''s projects.','["Start with the tool''s replacement cost. A good rule of thumb: your daily rental rate should be roughly 1–1.5% of the tool''s purchase price. A $400 drill earns $4–6 per day.","Offer daily, 3-day, and weekly rates. Weekly rates should be about 3× the daily rate (not 7×) — this encourages longer rentals, which reduce handling friction for you.","Factor in wear cost. High-wear tools (angle grinders, rotary hammers, sanders) should be priced slightly higher to cover consumables and earlier replacement.","Add a security deposit equal to 30–50% of the tool''s replacement cost. Collect it through OxSteed''s secure payment system — it''s held and released automatically when the tool is returned undamaged.","Review your pricing quarterly. If a tool is booked more than 10 days per month, raise the rate by $2–5/day. If it rarely rents, check whether the listing photos or description need improving before dropping the price."]'::jsonb,ARRAY['Replacement cost pricing','Tiered rate structure','Deposit calculation'],'[]'::jsonb,10,'published'),
('handle-tool-damage-claim','Handle a Tool Damage Claim','tool-rental','Medium',30,FALSE,'Tool damage will happen eventually. Having a documented process protects you, keeps the experience fair for renters, and lets you resolve disputes quickly.','["When the tool is returned, inspect it immediately — before the renter leaves if possible. Compare the condition to your pre-rental photos. Note any new damage in writing and photograph it.","Categorize the damage: normal wear (sharpened blades going dull, scuffs) vs. damage (cracked housing, missing parts, broken mechanisms). Normal wear is your cost of doing business; damage is chargeable.","Get a repair or replacement quote from a tool service center within 48 hours. The quote is your claim basis — don''t negotiate off the top of your head.","File the claim through OxSteed''s platform within 5 days of return. Submit your pre-rental photos, post-rental photos, and the repair quote. OxSteed mediates using the deposit first.","Communicate factually, not emotionally. State what happened, what it costs, and what evidence you have. Renters who understand the documented process are far more cooperative than those who feel accused."]'::jsonb,ARRAY['Pre/post rental inspection','Damage categorization','Claim documentation'],'[]'::jsonb,25,'published'),
('build-tool-rental-inventory','Build a Tool Rental Inventory','tool-rental','Easy',30,FALSE,'Starting a tool rental side business takes strategic purchasing, not just listing what you already own. Here''s how to build an inventory that earns.','["Start with tools that have high rental demand and poor local availability: scissor lifts, concrete mixers, pressure washers, tile saws, and large pipe wrenches rent frequently because most people don''t own them.","Buy used equipment in good mechanical condition rather than new. A used 10-inch miter saw at $150 that rents for $45/day pays for itself in four rentals.","Prioritize professional-grade tools over consumer grade. They hold up to repeated rentals, justify higher rates, and renters who need to do serious work want reliable equipment.","Maintain every tool before it goes out and after it comes back. A 5-minute clean and function check after each rental catches problems before the next renter discovers them mid-job.","Track each tool''s rental history and maintenance log in a spreadsheet. This data tells you which tools earn and which sit — so you know where to reinvest."]'::jsonb,ARRAY['Demand research','Used equipment sourcing','Maintenance scheduling'],'[{"name":"Maintenance log spreadsheet","rent":null,"buy":null}]'::jsonb,10,'published'),
('screen-tool-renters','Screen Renters and Reduce Damage Risk','tool-rental','Easy',20,FALSE,'Most renters treat equipment well. A short screening process identifies the small number who won''t — and it doesn''t have to be confrontational.','["Require ID verification through OxSteed before any rental. This alone eliminates most bad actors — people who intend to misuse equipment avoid platforms that verify identity.","For high-value tools (over $500 replacement cost), check the renter''s profile: How many completed rentals? Any negative reviews from other tool owners? A renter with 20 successful rentals is low risk.","Ask one screening question when you receive a rental request: ''What''s this tool for?'' The answer tells you whether they understand how to use it and whether the application is within your terms.","Collect the security deposit before the tool leaves your hands. OxSteed''s payment system handles this automatically — never hand over equipment before the deposit clears.","Meet renters at pickup if possible. A 2-minute face-to-face handover, where you walk through the tool''s condition and operation, sets a professional tone and reduces both accidents and disputes."]'::jsonb,ARRAY['Profile review','Deposit collection','In-person handover'],'[]'::jsonb,10,'published'),
('understand-oxsteed-franchise','Understand the OxSteed Franchise Model','franchise','Easy',30,TRUE,'An OxSteed franchise gives you a proven system, a known brand, and access to the platform''s customer base — in exchange for territory fees, royalties, and operating standards. Here''s what that means in practice.','["OxSteed franchisees operate a local services business under the OxSteed brand. You recruit and manage helpers, handle customer relationships in your territory, and drive local marketing — the platform handles tech, payment processing, and national brand support.","Understand the financial structure before applying: there is an initial franchise fee, a monthly royalty (percentage of gross revenue), and a marketing contribution. These are disclosed in the Franchise Disclosure Document (FDD) — read it with a lawyer.","Your territory is defined geographically. You have exclusive rights to place helpers and serve customers within that boundary. Territories are sized based on population and market data, not by the applicant.","Franchisees are held to OxSteed''s quality standards: response time, review minimums, helper vetting, and insurance requirements. Operating below standard triggers a performance improvement process.","The franchise relationship is contractual, typically 5–10 years with renewal options. Understand what triggers termination, what your exit options are, and whether you can sell the franchise before you sign anything."]'::jsonb,ARRAY['Franchise structure','FDD review','Territory rights'],'[]'::jsonb,10,'published'),
('evaluate-a-territory','Evaluate a Franchise Territory Before Applying','franchise','Medium',60,FALSE,'Not all territories are equal. The right territory has demand, low existing competition, and a demographics profile that fits OxSteed''s customer base. Here''s how to evaluate one before you commit.','["Pull the territory''s population and household count from the US Census Bureau''s American Community Survey (ACS). OxSteed''s home services model performs best in areas with 40,000–150,000 households, high homeownership rates, and median home values above $250K.","Research the existing local competition: number of licensed contractors per trade, presence of national home services companies (Angi, TaskRabbit), and local platform penetration. A market with high competition requires a clear differentiation plan.","Drive the territory. Note housing stock age (older homes need more maintenance), commercial density (business clients are high-value), and logistics geography (a geographically compact territory is more efficient to serve).","Talk to potential customers and helpers in the area before you apply. What services do people struggle to find? What do local handypeople earn? This qualitative data fills gaps that demographics can''t.","Build a simple 3-year revenue model: number of active customers × average annual spend × your take rate. Run conservative (50% of target), base, and optimistic (120%) scenarios. If the conservative case still covers your fees and a living wage, the territory merits a serious application."]'::jsonb,ARRAY['Demographic research','Competitive analysis','Revenue modeling'],'[{"name":"US Census Bureau ACS (census.gov)","rent":null,"buy":null}]'::jsonb,25,'published'),
('complete-franchise-application','Complete the OxSteed Franchise Application','franchise','Medium',45,FALSE,'The application process is two-way: OxSteed is evaluating you, and you should be evaluating OxSteed. Here''s how to approach it as a professional.','["Gather your financial documents before you start: 2 years of personal tax returns, a current personal financial statement (assets and liabilities), and proof of liquid capital. OxSteed will verify that you meet the minimum financial requirements.","Write a business plan summary: your territory selection rationale, your relevant experience, your network of potential helpers, and your 12-month launch strategy. This is your first opportunity to demonstrate that you can operate independently.","Request the Franchise Disclosure Document (FDD) from OxSteed''s franchise team. Federal law requires it be provided at least 14 days before you sign anything. Use that time to review it with a franchise attorney — not a general business attorney.","Speak with at least three existing OxSteed franchisees. Their contact information is in the FDD (Item 20). Ask: What surprised you in year one? What support from corporate has been most valuable? What would you do differently?","Submit your application through the OxSteed Franchise Portal. You''ll receive a response within 10 business days. If approved, a discovery day follows — an in-person meeting with the franchise team before final signing."]'::jsonb,ARRAY['Financial documentation','FDD review process','Franchisee due diligence'],'[]'::jsonb,25,'published'),
('franchise-financial-requirements','Understand Franchise Financial Requirements','franchise','Medium',45,FALSE,'Starting a franchise requires more capital than most people initially budget. Understanding all the cost components up front prevents cash flow problems in the critical first year.','["The initial franchise fee is the most visible cost but rarely the largest. Budget it as a sunk cost — it grants you the right to operate, not a guarantee of profit.","Working capital is often underestimated. You need reserves to cover operating expenses (your salary, vehicle costs, marketing, insurance) for 6–12 months before revenue covers them. Most new franchisees need $40,000–80,000 in working capital beyond the franchise fee.","Recurring costs include royalty (typically 5–8% of gross revenue), marketing fund contribution (1–3% of gross revenue), software/platform fees, and insurance. Model these as fixed monthly costs from day one.","Understand the ramp timeline. Most service franchises take 9–18 months to reach breakeven. Your financial model should account for this explicitly — not assume full productivity from month one.","Explore financing options: SBA 7(a) loans are commonly used for franchise purchases, and many lenders have pre-approved OxSteed as an eligible franchise. A ROBS structure lets you use retirement funds without an early withdrawal penalty — consult a specialist before using this route."]'::jsonb,ARRAY['Working capital planning','Royalty and fee modeling','SBA loan awareness'],'[]'::jsonb,25,'published'),
('first-90-days-as-franchisee','What to Expect in Your First 90 Days as a Franchisee','franchise','Easy',30,FALSE,'The first 90 days are about building momentum, not achieving scale. Here''s what to focus on and what to let go of until you''re stable.','["Days 1–30 are operational setup: entity formation, business banking, insurance certificates, helper recruitment, and completing OxSteed''s onboarding training. Nothing customer-facing should happen until you have at least 5 vetted, insured helpers ready.","Days 31–60 are soft launch: onboard your first 10–15 customers through personal outreach (neighbors, local Facebook groups, community boards). Fulfillment quality matters more than volume — your first reviews define your local reputation.","Days 61–90 are systems building: what worked in fulfillment? What took too long? Where did communication break down? Document your processes — hiring, dispatching, invoicing — so you can delegate them.","Track one metric above all others in the first 90 days: customer return rate. A customer who books twice in 90 days is a signal your quality is working. One who books and doesn''t return is a signal something failed.","Connect with other franchisees monthly. Their experience 6–12 months ahead of yours is the most relevant advice you''ll get — more so than corporate guidance, which is written for the average franchisee."]'::jsonb,ARRAY['Franchise launch sequencing','Soft launch strategy','Early operations documentation'],'[]'::jsonb,10,'published'),
('build-monthly-budget','Build a Personal Monthly Budget','life','Easy',30,TRUE,'A budget isn''t a punishment — it''s a picture of your money. Building one for the first time takes 30 minutes and immediately shows you where it''s going.','["List your monthly take-home income (after tax). Use your lowest recent month if it varies.","List fixed expenses: rent/mortgage, car payment, insurance, subscriptions, loan payments. These don''t change month to month.","List variable expenses from the last 2–3 bank statements: groceries, gas, dining, entertainment, shopping. Average them. Most people underestimate this by 20–30%.","Subtract fixed + variable from income. What remains is your savings capacity. If it''s negative, identify the largest discretionary category and set a target to reduce it by 25%.","Use the 50/30/20 framework as a starting target: 50% to needs, 30% to wants, 20% to savings and debt repayment. Adjust based on your actual situation — the framework is a guide, not a rule."]'::jsonb,ARRAY['Income tracking','Expense categorization','Savings calculation'],'[{"name":"Spreadsheet (Google Sheets or Excel)","rent":null,"buy":null},{"name":"Banking app with transaction export","rent":null,"buy":null}]'::jsonb,10,'published'),
('track-vehicle-maintenance','Track Your Vehicle Maintenance','life','Easy',20,FALSE,'Keeping a simple vehicle maintenance log protects your warranty, extends the life of your car, and saves money by catching small problems before they become large ones.','["Create a log: a notes app, a dedicated app (CarFax, Drivvo), or a glove box notepad. Record the date, mileage, and work done for every service.","Know your manufacturer''s maintenance intervals. They''re in your owner''s manual. The major milestones: oil change (every 5,000–7,500 miles for modern cars on synthetic), tire rotation (every 5,000–7,500 miles), cabin air filter (every 15,000 miles), brake inspection (annually), coolant flush (every 50,000–100,000 miles).","Set phone reminders based on current mileage. If you drove 12,000 miles last year, you need roughly one service every 3 months — adjust for your actual mileage.","Keep every receipt. Documented maintenance history increases resale value — buyers and dealers pay more for a car with records than one without them.","When a warning light comes on, look it up before ignoring it. A TPMS (tire pressure) light is a $2 fix. An engine light can be a $10 gas cap or a $2,000 catalytic converter — you need to know which before you drive another 3,000 miles."]'::jsonb,ARRAY['Maintenance interval tracking','Warning light triage','Resale documentation'],'[{"name":"Vehicle maintenance app (Drivvo or Carfax Care)","rent":null,"buy":null},{"name":"OBD-II Bluetooth scanner (reads check engine codes)","rent":null,"buy":"https://www.amazon.com/s?k=bluetooth+obd2+scanner+elm327&tag=oxsteed-20"}]'::jsonb,10,'published'),
('create-home-maintenance-calendar','Build a Home Maintenance Calendar','life','Easy',30,FALSE,'A home maintenance calendar turns reactive, expensive repairs into predictable, affordable tasks. Most major home systems fail not from age, but from neglect.','["List every major system in your home: HVAC, water heater, gutters, roof, smoke detectors, exterior caulk, windows and doors, appliances. This is your asset list.","Assign a frequency to each: HVAC filter (monthly/quarterly), gutters (twice/year), smoke detector batteries (annually), water heater flush (annually), dryer vent clean (annually), roof inspection (annually), exterior caulk (every 2–3 years).","Group tasks by season. Spring: gutters, HVAC service, exterior inspection. Summer: pest inspection, AC check. Fall: weatherstripping, dryer vent, water heater anode rod. Winter: pipe insulation check, smoke and CO detectors.","Put the calendar tasks in your phone calendar with a reminder. Set them to repeat. This is the entire system — a recurring calendar entry is the difference between maintaining a home and falling behind on one.","When you complete a task, photograph the work and log the date in a home maintenance notes file. This record supports insurance claims, contractor conversations, and eventual resale."]'::jsonb,ARRAY['Maintenance scheduling','Seasonal task grouping','Documentation habits'],'[{"name":"Phone calendar or Notion/Google Calendar","rent":null,"buy":null}]'::jsonb,10,'published'),
('build-emergency-fund','Build a 3-Month Emergency Fund','life','Medium',45,FALSE,'An emergency fund isn''t savings — it''s insurance. Three months of expenses means a job loss, a medical bill, or a car repair doesn''t force you into debt.','["Calculate your 3-month target. Add up your actual monthly essential expenses: rent/mortgage, utilities, food, transportation, insurance, minimum debt payments. Multiply by 3. This is your number.","Open a dedicated high-yield savings account (not your checking account). Separation makes the money harder to spend casually. HYSA rates as of 2026 are significantly better than standard savings — shop Marcus, Ally, or SoFi.","Set up an automatic transfer on payday — even $50/week adds up to $2,600/year. Automation removes the decision. You build the fund without thinking about it.","Fund it faster by redirecting windfalls: tax refund, overtime, gift money, selling unused items. One-time deposits cut your timeline significantly.","Once funded, don''t touch it for non-emergencies. A car repair is an emergency. A vacation is not. When you do use it, replenish it before any other savings goal."]'::jsonb,ARRAY['Expense calculation','HYSA selection','Automatic savings setup'],'[{"name":"High-yield savings account (Ally, Marcus, or SoFi)","rent":null,"buy":null}]'::jsonb,25,'published'),
('negotiate-a-service-bill','Negotiate a Service Bill or Subscription','life','Easy',20,FALSE,'Most people pay whatever bill arrives without question. Negotiating — or simply asking for a lower rate — works surprisingly often. Cable, internet, insurance, and gym memberships are the most negotiable.','["Research competitor rates before you call. Go to two or three competing providers and get their current new-customer pricing. This is your leverage.","Call the customer retention department directly — not general customer service. Say: ''I''ve been a customer for X years and I''m considering switching. I''d like to see if you can match [competitor''s rate].''","Be calm, specific, and willing to follow through. ''I have a quote from [competitor] for $45/month. Can you match that?'' works better than ''I want a discount.''","If they can''t match the price, ask for a temporary promotion or a loyalty credit. These are often available even when a rate match isn''t.","If negotiating fails: actually switch, or document the call and try again in 3 months with a different representative. Companies run different promotions at different times."]'::jsonb,ARRAY['Competitive research','Retention department scripting','Escalation timing'],'[]'::jsonb,10,'published'),
('understand-your-insurance-coverage','Understand What Your Home and Auto Insurance Actually Covers','life','Medium',45,FALSE,'Most people discover what their insurance doesn''t cover right after they need it. A 45-minute policy review prevents that — and often reveals coverage you''re already paying for but didn''t know about.','["Pull your declarations page for both home and auto insurance. This one-page summary shows your coverage limits, deductibles, and exclusions. Read it before anything else.","For home insurance: understand the difference between dwelling coverage (the structure), personal property (your stuff), and liability (if someone gets hurt on your property). Confirm your dwelling limit actually covers the cost to rebuild — not the market value, the rebuild cost.","For auto insurance: confirm you have collision (damage to your car in an accident) and comprehensive (theft, weather, fire) if your car is worth more than $5,000. If you have a loan, both are likely required.","Identify your deductibles. A $2,500 deductible on home insurance means you pay the first $2,500 of any claim. Higher deductibles lower premiums but require more liquid reserves.","Call your agent once per year and ask two questions: ''Is there any coverage I''m paying for that I''m probably not using?'' and ''Is there coverage I should have that I don''t?'' Most agents will answer honestly — it''s a 15-minute call that often saves money."]'::jsonb,ARRAY['Declarations page reading','Coverage limit assessment','Deductible analysis'],'[]'::jsonb,25,'published'),
('analyze-rental-yield','Calculate Gross and Net Rental Yield','management','Medium',30,FALSE,'Rental yield is the return your property generates relative to its cost. Knowing how to calculate both gross and net yield — and what''s realistic in your market — is fundamental to evaluating any rental investment.','["Gross yield: Annual rent ÷ Purchase price × 100. A property that rents for $1,800/month ($21,600/year) purchased for $270,000 has a gross yield of 8%. This is your headline number.","Net yield accounts for actual expenses. Subtract from annual rent: property taxes, insurance, property management (typically 8–12% of rent), vacancy allowance (5–8%), maintenance reserve (1% of property value/year), and HOA fees if applicable.","For a property with $21,600 annual rent and $10,200 in annual expenses, net income is $11,400. Net yield = $11,400 ÷ $270,000 = 4.2%.","Compare your net yield to alternatives: a HYSA at 4.5–5% carries zero management burden. A rental at 4% net yield only makes sense if you''re also building equity and expecting appreciation.","Calculate cash-on-cash return if you''re financing. This is net income ÷ actual cash invested (down payment + closing costs + initial repairs). This figure tells you how efficiently your capital is working."]'::jsonb,ARRAY['Gross yield formula','Expense estimation','Cash-on-cash return'],'[{"name":"Spreadsheet for yield modeling","rent":null,"buy":null}]'::jsonb,25,'published'),
('evaluate-contractor-bids-investor','Evaluate Contractor Bids as an Investor','management','Medium',45,FALSE,'A low bid and a good bid are not the same thing. Evaluating contractor proposals with a consistent framework protects your budget and your timeline.','["Collect at least three bids for any project over $3,000. Fewer bids means less price visibility; more than five becomes unwieldy. Ensure all bidders are working from the same scope document — you can''t compare bids on different scopes.","Review each bid for completeness: Does it specify materials by brand and grade? Does it list what''s excluded? Does it include a payment schedule? A bid that''s vague on materials will be vague on delivery.","Check licensing and insurance before anything else. General contractor license, liability insurance, and workers'' comp are non-negotiable for any work on a property you own. Ask for certificates.","Evaluate the payment schedule as a risk indicator. Never pay more than 10% upfront on a job under $10,000. A contractor who demands 50% upfront before starting has cash flow problems — that''s your risk.","Contact references for the top two bidders. Ask: Was the project completed on time? Did the final cost match the bid? Would you hire them again for a larger project? Three references, three calls, 15 minutes total — worth every minute."]'::jsonb,ARRAY['Scope comparison','License and insurance verification','Payment schedule evaluation'],'[]'::jsonb,25,'published'),
('set-up-your-business-on-oxsteed','Set Up Your Business on OxSteed','business','Easy',10,TRUE,'A complete business profile on OxSteed unlocks bulk pricing, business invoicing, helper team management, and priority placement. Here''s how to set it up right.','["Switch your account to a Business account in Settings.","Add your business name, EIN, and primary service categories.","Upload your business license and any relevant trade certifications.","Set your service area, business hours, and response time commitment.","Add your team — invite helpers as employees or subcontractors.","Enable business invoicing so clients can pay by ACH or card on net terms."]'::jsonb,ARRAY['Business profile setup','Team management','Invoicing'],'[]'::jsonb,10,'published'),
('manage-business-invoicing','Manage Business Invoicing on OxSteed','business','Easy',8,FALSE,'Business invoicing lets you bill clients directly from OxSteed — with net terms, payment tracking, and automated reminders. Here''s how to use it end to end.','["Enable business invoicing in your account settings.","Create an invoice from any completed job or as a standalone document.","Set payment terms: Net 15, Net 30, or due on receipt.","Send the invoice — the client receives a payment link by email.","Track outstanding invoices in your Billing dashboard.","Enable auto-reminders at 7 days and 1 day before due date."]'::jsonb,ARRAY['Invoicing','Payment tracking','Net terms'],'[]'::jsonb,10,'published'),
('grow-your-business-on-oxsteed','Grow Your Business on OxSteed','business','Medium',15,FALSE,'OxSteed offers business owners multiple levers for growth: placement optimization, referral programs, anchor client relationships, and team expansion. This guide covers all four.','["Optimize your placement: maintain a response time under 2 hours and review score above 4.7.","Activate the business referral program — each referred business earns you platform credits.","Identify your top 3 clients and propose a service retainer for recurring work.","Review your job acceptance rate monthly — anything below 60% signals pricing or capacity issues.","Hire your next helper when your utilization stays above 80% for 3 consecutive weeks."]'::jsonb,ARRAY['Growth strategy','Client retention','Hiring triggers'],'[]'::jsonb,25,'published'),
('run-daily-operations','Run Daily Operations as a Manager','management','Easy',10,FALSE,'A manager''s day on OxSteed is dashboard-first: job queue, helper status, and client communications. Here''s the daily operating rhythm that keeps everything running.','["Check the job queue at start of day: open, in-progress, and awaiting review.","Confirm all helpers scheduled for today have checked in.","Review any overnight messages or escalations from clients.","Resolve any flagged jobs before noon — delays compound.","End-of-day: review completions, approve invoices, note any follow-ups."]'::jsonb,ARRAY['Scheduling','Operations management','Escalation handling'],'[]'::jsonb,10,'published'),
('manage-client-relationships','Manage Client Relationships at Scale','management','Medium',12,FALSE,'Managing multiple client relationships without dropping the ball requires a system. Here''s how to track, communicate, and retain clients at volume.','["Segment clients: new (first 3 jobs), active (regular), and at-risk (no job in 60 days).","Set a check-in cadence for each segment: weekly for new, monthly for active, immediate for at-risk.","Use OxSteed''s messaging templates for routine communications.","Log every client issue and its resolution in the job notes — this builds your service history.","Review at-risk clients quarterly and reach out personally before they churn."]'::jsonb,ARRAY['CRM basics','Client segmentation','Retention'],'[]'::jsonb,25,'published'),
('prospect-local-clients','Prospect Local Clients on OxSteed','sales','Easy',10,TRUE,'OxSteed gives sales reps a local prospect universe: businesses posting jobs, helpers building teams, and property managers sourcing labor. Here''s how to identify and approach the right ones.','["Filter the marketplace by your target category and zip code.","Identify businesses with high job post volume but low helper retention.","Build a prospect list: business name, contact, job categories, monthly volume.","Craft an outreach message that references a specific job they posted.","Follow up once at 5 days if no response — then move on."]'::jsonb,ARRAY['Prospecting','Local market research','Outreach'],'[]'::jsonb,10,'published'),
('close-service-agreements','Close Service Agreements with Local Businesses','sales','Medium',12,FALSE,'A service agreement turns a one-time job into a recurring revenue relationship. Here''s how to position, negotiate, and close retainer-style agreements with local business clients.','["Identify clients who have used your services 3+ times in the last 90 days.","Calculate their current monthly spend — this is your retainer floor.","Propose a retainer at a 10–15% discount in exchange for a 3-month commitment.","Include service level commitments: response time, dedicated helper, priority scheduling.","Send the agreement through OxSteed business invoicing for countersignature."]'::jsonb,ARRAY['Service agreement negotiation','Retainer pricing','Contract basics'],'[]'::jsonb,25,'published'),
('build-a-referral-pipeline','Build a Referral Pipeline','sales','Easy',8,FALSE,'The best sales pipeline is one that builds itself. Learn how to systematize referrals from happy clients so you spend less time prospecting and more time serving.','["Identify your top 10 happiest clients by review score and tenure.","Ask each one for one introduction — not a referral in general, a specific person.","Create a referral incentive: platform credits, rate discount, or a simple thank-you.","Track every referral source so you know which clients generate the most introductions.","Reinvest referral time savings into serving your best clients better."]'::jsonb,ARRAY['Referral generation','Client networking','Pipeline management'],'[]'::jsonb,10,'published'),
('handle-first-contact-support','Handle First-Contact Support Like a Pro','support','Easy',10,TRUE,'First-contact resolution — solving the issue without a transfer or follow-up — is the gold standard in support. Here''s the framework for making it happen on OxSteed.','["Greet with name and confirm the issue in your own words before solving.","Pull up the job record, payment history, and message thread before responding.","Use the decision tree: billing → payment log first; quality → job completion record first.","State your resolution clearly, including any timelines for credits or refunds.","Ask if the resolution fully addresses the issue before closing.","Document the issue type and resolution in the case notes for pattern tracking."]'::jsonb,ARRAY['Issue resolution','Active listening','Documentation'],'[]'::jsonb,10,'published'),
('resolve-job-disputes','Resolve Job Disputes Fairly and Fast','support','Medium',12,FALSE,'Job disputes — quality complaints, payment disagreements, no-shows — are the most emotionally charged support interactions. Here''s the evidence-based resolution framework that keeps both parties satisfied.','["Pull all evidence first: job post, bid, messages, photos, and completion status.","Hear each party separately — never in a group message thread.","Apply the resolution matrix: who has the documented evidence?","Offer resolution options rather than a single imposed decision where possible.","Close the case with a written summary of the resolution and any credits issued.","Flag repeated-dispute accounts for trust and safety review."]'::jsonb,ARRAY['Dispute resolution','Evidence evaluation','De-escalation'],'[]'::jsonb,25,'published'),
('de-escalate-difficult-conversations','De-escalate Difficult Conversations','support','Medium',10,FALSE,'Angry customers and frustrated helpers are a daily reality in marketplace support. Here''s the communication framework that turns escalations into resolutions — without burning out.','["Let the person finish without interrupting — don''t problem-solve until they''re done.","Acknowledge the frustration before explaining anything.","Avoid defensive language: ''our policy says'' → ''here''s what I can do for you.''","State what you can do, then what you can''t — never the reverse.","Set a specific timeline: ''I''ll have an update for you by 3pm tomorrow'' not ''soon.''","Close by confirming understanding: ''Does this resolution work for you?''"]'::jsonb,ARRAY['De-escalation','Empathetic communication','Conflict resolution'],'[]'::jsonb,25,'published'),
('book-a-helper-directly','Book a Helper Directly Without Posting a Job','customer','Easy',6,FALSE,'Direct booking lets you request a specific helper and time without putting your job in front of strangers. If you already trust someone, this is faster and more private.','["Find the helper''s public profile via the helper directory or a shared link.","Tap ''Book'' — choose the service, date, and time you need.","Add a note with any specific details the helper needs to know.","Wait for the helper to confirm — you''ll get a notification when they accept.","If the helper declines or doesn''t respond, you can convert the request into a public job."]'::jsonb,ARRAY['Direct booking','Private scheduling','Repeat hiring'],'[]'::jsonb,10,'published'),
('use-planned-needs','Plan Future Services So You''re Never Surprised','life','Easy',10,TRUE,'Planned Needs turns future expenses into a daily savings habit. Instead of being blindsided by a big repair, you see it coming and reserve money in advance.','["Go to Planned Needs and tap ''Add a need.''","Name the need: ''HVAC service,'' ''brake replacement,'' ''gutter cleaning.''","Set an estimated cost and a target date.","OxSteed calculates how much to set aside per day, week, or month.","When the date approaches, convert the planned need into a job post in one tap.","Assign a preferred helper so they get first look when the job goes live."]'::jsonb,ARRAY['Future planning','Sinking funds','Service scheduling'],'[]'::jsonb,10,'published'),
('manage-helper-calendar','Manage Your Availability and Calendar','helper','Easy',8,FALSE,'A well-managed calendar means no overbooking, fewer cancellations, and customers who trust your reliability. Here''s how to keep your availability accurate on OxSteed.','["Open your dashboard and go to the Calendar tab.","Block out any days or times you''re unavailable.","Set your standard weekly availability so customers see accurate open slots.","Review incoming booking requests within 2 hours — expired requests hurt your ranking.","Reschedule instead of canceling when possible — cancellations reduce your placement score.","Set appointment reminders so you never miss a confirmed job."]'::jsonb,ARRAY['Calendar management','Availability setting','Booking management'],'[]'::jsonb,10,'published'),
('set-goals-on-oxsteed','Set and Track Goals on OxSteed','life','Easy',8,FALSE,'Goals connect your dashboard activity to what actually matters — saving for a service, organizing your home, or building a more reliable maintenance routine.','["Go to the Goals tab in your dashboard.","Create a goal: give it a name, target, and deadline.","Link a sinking fund or planned need if the goal has a financial component.","Review progress once a week — the dashboard shows how close you are.","Mark goals complete and create the next one when you''re done."]'::jsonb,ARRAY['Goal setting','Progress tracking','Financial planning'],'[]'::jsonb,10,'published'),
('understand-payment-protection','How OxSteed Payment Protection Works','customer','Easy',8,FALSE,'Paying through OxSteed keeps your money safe. Understand how escrow-style job payments, invoices, and refund protection work — and why paying off-platform puts you at risk.','["Always pay through OxSteed — never send cash, Venmo, or Zelle to a helper.","For jobs, your payment is held until work is confirmed complete.","If work isn''t done as described, open a dispute before releasing payment.","For invoices, you have the payment record as proof for any future dispute.","If a helper asks you to pay off-platform, report it — it violates OxSteed terms."]'::jsonb,ARRAY['Payment safety','Dispute basics','Escrow understanding'],'[]'::jsonb,10,'published'),
('use-messages-to-prevent-disputes','Use Messaging to Prevent Disputes','customer','Easy',6,FALSE,'Most job disputes come from mismatched expectations that could have been caught in a message. Here''s how to use OxSteed messaging to keep scope clear and protect both parties.','["Ask clarifying questions in OxSteed messages before accepting a bid — not by phone or text.","Confirm scope in writing: ''So you''ll handle removal and haul-away, correct?''","If anything changes during the job, update scope in the message thread.","Take photos before the helper starts and ask them to do the same.","Don''t mark a job complete until you''re satisfied — message the helper first if something is off."]'::jsonb,ARRAY['Scope documentation','In-platform communication','Pre-dispute resolution'],'[]'::jsonb,10,'published'),
('use-qr-codes-to-win-offline-leads','Win Offline Leads with QR Codes','helper','Easy',6,FALSE,'Your best leads often come from people who meet you in person. A QR code bridges the gap between that offline first impression and a booked job on OxSteed.','["Go to your OxSteed dashboard and open the QR Code generator.","Generate a QR code that links to your public profile and booking page.","Add it to your business card, invoice, truck decal, flyer, or job site sign.","When someone scans it, they land on your full profile with booking enabled.","Track the profile views and booking requests that come from new contacts."]'::jsonb,ARRAY['QR codes','Offline marketing','Profile sharing'],'[]'::jsonb,10,'published'),
('master-the-business-hub','Master the Business Hub Workspace','business','Medium',15,TRUE,'Business Hub is a 35-tab operations workspace covering finance, scheduling, team management, marketing, and analytics. This guide orients you to the tabs that matter most on day one.','["Open Business Hub from the navbar.","Start in Overview: revenue, jobs, bookings, messages, and trend lines are all here.","Set up your Services tab — every bookable service must be defined before slots are available.","Configure Hours so the booking engine knows your real availability.","Go to Team and invite your first manager or representative.","Visit Health to see what''s incomplete and what OxSteed recommends you fix next."]'::jsonb,ARRAY['Business Hub navigation','Service setup','Team access control'],'[]'::jsonb,25,'published'),
('sell-products-on-oxsteed','Sell Products Through the OxSteed Marketplace','business','Medium',12,FALSE,'If your business has physical products — supplies, kits, parts, or materials — you can list them on the OxSteed marketplace alongside your services.','["Go to Business Hub → Products tab.","Add each product: name, description, photos, price, and stock quantity.","Toggle ''Publish to Marketplace'' to make it visible to buyers.","Set pricing rules if you want bulk discounts or segment-specific pricing.","Manage orders from the Orders tab — fulfill and mark shipped from there.","Use stock snapshots to avoid overselling: OxSteed reserves stock atomically at checkout."]'::jsonb,ARRAY['Product listing','Inventory management','Marketplace publishing'],'[]'::jsonb,25,'published'),
('secure-your-account','Secure Your OxSteed Account','life','Easy',8,FALSE,'Your OxSteed account holds your payment methods, job history, and personal information. Ten minutes of security setup protects all of it.','["Enable two-factor authentication (2FA) in Settings → Security.","Verify your email address so you receive alerts for account changes.","Review connected devices and sign out of any you don''t recognize.","Set notification preferences for logins, payment activity, and profile changes.","Use a unique password — never reuse one from another account."]'::jsonb,ARRAY['Two-factor authentication','Account security','Notification setup'],'[]'::jsonb,10,'published')
) AS seed(id, title, category, difficulty, minutes, featured, intro, steps, skills, tools, xp, status)
WHERE NOT EXISTS (SELECT 1 FROM learn_guides lg WHERE lg.id = seed.id);
